import 'package:flutter/material.dart';
import 'qa_5000_catalog.dart';

enum IslamicQaCategory {
  jannah, // الجنة ونعيمها وأبوابها (1-50)
  aqeedah, // العقيدة والإيمان واليوم الآخر (51-100)
  taharah, // الطهارة والوضوء والغسل (101-150)
  prayer, // الصلاة والخشوع والفوائت والسهو (151-200)
  quran, // القرآن الكريم والتلاوة والتفسير (201-250)
  fastingZakahHajj, // الصيام والزكاة والحج والصدقات (251-300)
  dhikrDua, // الأذكار والدعاء والرقية والرؤى (301-350)
  seerah, // السيرة النبوية والصحابة (351-400)
  familyEthics, // الأسرة وبر الوالدين والأخلاق (401-450)
  lifeTawbah, // التوبة والمعاملات وأسئلة العصر (451-500)
}

extension IslamicQaCategoryExt on IslamicQaCategory {
  String get arabicTitle {
    switch (this) {
      case IslamicQaCategory.jannah:
        return 'الجنة ونعيمها';
      case IslamicQaCategory.aqeedah:
        return 'العقيدة والآخرة';
      case IslamicQaCategory.taharah:
        return 'الطهارة والوضوء';
      case IslamicQaCategory.prayer:
        return 'الصلاة والفوائت';
      case IslamicQaCategory.quran:
        return 'القرآن والتفسير';
      case IslamicQaCategory.fastingZakahHajj:
        return 'الصيام والزكاة والحج';
      case IslamicQaCategory.dhikrDua:
        return 'الدعاء والرقية';
      case IslamicQaCategory.seerah:
        return 'السيرة والصحابة';
      case IslamicQaCategory.familyEthics:
        return 'الأسرة والأخلاق';
      case IslamicQaCategory.lifeTawbah:
        return 'التوبة والمعاملات';
    }
  }

  IconData get icon {
    switch (this) {
      case IslamicQaCategory.jannah:
        return Icons.castle_rounded;
      case IslamicQaCategory.aqeedah:
        return Icons.light_mode_rounded;
      case IslamicQaCategory.taharah:
        return Icons.water_drop_rounded;
      case IslamicQaCategory.prayer:
        return Icons.mosque_rounded;
      case IslamicQaCategory.quran:
        return Icons.menu_book_rounded;
      case IslamicQaCategory.fastingZakahHajj:
        return Icons.nights_stay_rounded;
      case IslamicQaCategory.dhikrDua:
        return Icons.auto_awesome_rounded;
      case IslamicQaCategory.seerah:
        return Icons.history_edu_rounded;
      case IslamicQaCategory.familyEthics:
        return Icons.favorite_rounded;
      case IslamicQaCategory.lifeTawbah:
        return Icons.volunteer_activism_rounded;
    }
  }

  Color get color {
    switch (this) {
      case IslamicQaCategory.jannah:
        return const Color(0xFF10B981);
      case IslamicQaCategory.aqeedah:
        return const Color(0xFFF59E0B);
      case IslamicQaCategory.taharah:
        return const Color(0xFF0EA5E9);
      case IslamicQaCategory.prayer:
        return const Color(0xFF14B8A6);
      case IslamicQaCategory.quran:
        return const Color(0xFFD97706);
      case IslamicQaCategory.fastingZakahHajj:
        return const Color(0xFF8B5CF6);
      case IslamicQaCategory.dhikrDua:
        return const Color(0xFFEC4899);
      case IslamicQaCategory.seerah:
        return const Color(0xFF6366F1);
      case IslamicQaCategory.familyEthics:
        return const Color(0xFFEF4444);
      case IslamicQaCategory.lifeTawbah:
        return const Color(0xFF06B6D4);
    }
  }
}

class IslamicQaItem {
  final int number;
  final String id;
  final IslamicQaCategory category;
  final String sectionTitle;
  final String question;
  final String answer;
  final String evidence;
  final List<String> tags;

  const IslamicQaItem({
    required this.number,
    required this.id,
    required this.category,
    this.sectionTitle = 'أحكام عامة',
    required this.question,
    required this.answer,
    required this.evidence,
    this.tags = const [],
  });
}

class IslamicQaSearchMatch {
  final IslamicQaItem item;
  final int score;

  const IslamicQaSearchMatch({
    required this.item,
    required this.score,
  });
}

class IslamicQaSearchResult {
  final String query;
  final List<IslamicQaSearchMatch> matches;
  final String smartSummary;

  const IslamicQaSearchResult({
    required this.query,
    required this.matches,
    required this.smartSummary,
  });

  bool get hasDirectAnswer => matches.isNotEmpty;
}

class IslamicQaCatalog {
  static List<IslamicQaItem>? _cachedAll;

  static List<IslamicQaItem> get allQuestions =>
      _cachedAll ??= List<IslamicQaItem>.unmodifiable(_buildAll5000());

  static List<IslamicQaItem> byCategory(IslamicQaCategory category) =>
      allQuestions.where((q) => q.category == category).toList(growable: false);

  static List<String> sectionsForCategory(IslamicQaCategory category) =>
      Qa5000ExpansionCatalog.subsectionsByCategory[category] ?? const [];

  static List<IslamicQaItem> byCategoryAndSection(
    IslamicQaCategory category,
    String? sectionTitle,
  ) {
    if (sectionTitle == null || sectionTitle.isEmpty) {
      return byCategory(category);
    }
    return allQuestions
        .where((q) => q.category == category && q.sectionTitle == sectionTitle)
        .toList(growable: false);
  }

  static String normalizeArabic(String input) {
    var s = input.trim().toLowerCase();
    // إزالة التشكيل والهمزات والرموز
    s = s.replaceAll(RegExp(r'[\u064B-\u065F\u0670\u0640]'), '');
    s = s.replaceAll('أ', 'ا').replaceAll('إ', 'ا').replaceAll('آ', 'ا');
    s = s.replaceAll('ى', 'ي').replaceAll('ة', 'ه').replaceAll('ؤ', 'و').replaceAll('ئ', 'ي');
    s = s.replaceAll(RegExp(r'[؟\?\.،,!؛:"\(\)\[\]\-\—/]+'), ' ');
    s = s.replaceAll(RegExp(r'\s+'), ' ').trim();
    return s;
  }

  static const Map<String, List<String>> _colloquialSynonyms = {
    'ايه': ['ما', 'حكم', 'ماذا'],
    'ازاي': ['كيف', 'طريقه', 'كيفيه'],
    'امتي': ['متي', 'وقت'],
    'فين': ['اين', 'مكان'],
    'عوز': ['اريد', 'كيف', 'ابني'],
    'عايز': ['اريد', 'كيف', 'ابني'],
    'عاوز': ['اريد', 'كيف', 'ابني'],
    'ينفع': ['هل يجوز', 'حكم', 'يصح'],
    'حرام': ['حكم', 'يجوز', 'معصيه'],
    'حلال': ['مباح', 'يجوز', 'حكم'],
    'فوت': ['فائت', 'قضاء', 'نسيان'],
    'فوتت': ['فائت', 'قضاء', 'نسيان'],
    'مبطلات': ['نواقض', 'مفسدات'],
    'تفسد': ['تبطل', 'نواقض'],
    'بيبطل': ['ينقض', 'يفسد'],
    'فلوس': ['مال', 'زكاه', 'ربا', 'دين'],
    'مراتي': ['زوجه', 'زوج', 'اسره'],
    'جوزي': ['زوج', 'اسره'],
    'الجنه': ['جنه', 'فردوس', 'نعيم', 'قصور'],
    'ربنا': ['الله', 'توبه', 'دعاء'],
    'النبي': ['رسول', 'محمد', 'سنه'],
    'الرسول': ['نبي', 'محمد', 'سنه'],
    'بصلي': ['صلاه', 'وضوء', 'خشوع'],
    'اصلي': ['صلاه', 'ركعه', 'قضاء'],
    'شراب': ['خفين', 'جورب', 'مسح'],
    'الشراب': ['خفين', 'جورب', 'مسح'],
    'قران': ['قران', 'سوره', 'ايه', 'تلاوه'],
    'اذكار': ['ذكر', 'تسبيح', 'دعاء'],
    'كوابيس': ['رؤيا', 'احلام', 'حلم'],
    'احلام': ['رؤيا', 'تعبير'],
    'بركه': ['رزق', 'تيسير'],
    'توبه': ['استغفار', 'ذنب', 'مغفره'],
    'ذنوب': ['ذنب', 'توبه', 'استغفار'],
  };

  static const Set<String> _stopWords = {
    'هل',
    'ما',
    'في',
    'من',
    'علي',
    'الي',
    'عن',
    'ان',
    'او',
    'و',
    'ال',
    'لو',
    'هو',
    'هي',
    'لي',
    'لك',
    'مع',
    'كل',
    'بين',
    'عند',
    'بعد',
    'قبل',
    'هذا',
    'هذه',
    'التي',
    'الذي',
    'يا',
    'لا',
    'اذا',
    'كان',
    'يكون',
  };

  static IslamicQaSearchResult answerAnyQuestion(
    String rawQuery, {
    IslamicQaCategory? categoryFilter,
    int maxResults = 35,
  }) {
    final normalizedQuery = normalizeArabic(rawQuery);
    final baseList = categoryFilter == null ? allQuestions : byCategory(categoryFilter);

    if (normalizedQuery.isEmpty) {
      return IslamicQaSearchResult(
        query: rawQuery,
        matches: baseList
            .take(maxResults)
            .map((e) => IslamicQaSearchMatch(item: e, score: 100))
            .toList(growable: false),
        smartSummary:
            'اكتب أي سؤال في بالك بالعامية أو الفصحى وسيقوم محرك الفردوس بالبحث الفوري في 5000 سؤال وجواب موثق ومنظم في 50 قسماً فرعياً.',
      );
    }

    final rawTokens = normalizedQuery
        .split(' ')
        .where((t) => t.length >= 2 && !_stopWords.contains(t))
        .toList();
    final expandedTokens = <String>{...rawTokens};
    for (final t in rawTokens) {
      if (_colloquialSynonyms.containsKey(t)) {
        expandedTokens.addAll(_colloquialSynonyms[t]!);
      }
      if (t.startsWith('ال') && t.length > 3) {
        final noAl = t.substring(2);
        expandedTokens.add(noAl);
        if (_colloquialSynonyms.containsKey(noAl)) {
          expandedTokens.addAll(_colloquialSynonyms[noAl]!);
        }
      }
    }

    final scored = <IslamicQaSearchMatch>[];
    for (final item in baseList) {
      final nQ = normalizeArabic(item.question);
      final nA = normalizeArabic(item.answer);
      final nCat = normalizeArabic(item.category.arabicTitle);
      final nTags = item.tags.map(normalizeArabic).join(' ');

      int score = 0;
      if (nQ.contains(normalizedQuery)) {
        score += 120;
      }
      if (nTags.contains(normalizedQuery)) {
        score += 80;
      }

      for (final tok in expandedTokens) {
        if (nQ.contains(tok)) score += 28;
        if (nTags.contains(tok)) score += 22;
        if (nCat.contains(tok)) score += 14;
        if (nA.contains(tok)) score += 10;
      }

      if (score > 0) {
        scored.add(IslamicQaSearchMatch(item: item, score: score));
      }
    }

    scored.sort((a, b) {
      final cmp = b.score.compareTo(a.score);
      if (cmp != 0) return cmp;
      return a.item.number.compareTo(b.item.number);
    });

    final topMatches = scored.take(maxResults).toList(growable: false);
    if (topMatches.isEmpty) {
      return IslamicQaSearchResult(
        query: rawQuery,
        matches: const [],
        smartSummary:
            'لم نجد تطابقاً حرفياً لهذا النص ضمن الـ 5000 سؤال وجواب. جرّب كتابة كلمة مفتاحية أوضح (مثل: الجنة، القضاء، الوضوء، التوبة، الصيام، الزكاة، الرزق) أو تصفح الأقسام العشرة.',
      );
    }

    final best = topMatches.first.item;
    final others = topMatches.length - 1;
    final summary = others > 0
        ? 'أقرب إجابة لسؤالك من قسم «${best.category.arabicTitle}» (إضافة إلى $others إجابات ذات صلة).'
        : 'تم العثور على الإجابة المطابقة في قسم «${best.category.arabicTitle}».';

    return IslamicQaSearchResult(
      query: rawQuery,
      matches: topMatches,
      smartSummary: summary,
    );
  }

  static List<IslamicQaItem> _buildAll5000() {
    final result = <IslamicQaItem>[];

    void addCategory(
      IslamicQaCategory category,
      List<({String q, String a, String e, List<String> t})> entries,
    ) {
      int catIdx = 0;
      for (final entry in entries) {
        final numIdx = result.length + 1;
        result.add(
          IslamicQaItem(
            number: numIdx,
            id: 'qa_${numIdx.toString().padLeft(4, '0')}',
            category: category,
            sectionTitle: Qa5000ExpansionCatalog.subsectionFor(category, catIdx ~/ 10),
            question: entry.q,
            answer: entry.a,
            evidence: entry.e,
            tags: entry.t,
          ),
        );
        catIdx++;
      }
    }

    // =========================================================================
    // 1. الجنة ونعيمها وأبوابها ودرجاتها (1 - 50)
    // =========================================================================
    addCategory(IslamicQaCategory.jannah, [
      (
        q: 'ما هو الفردوس الأعلى ولماذا نصحنا النبي ﷺ بسؤاله؟',
        a: 'الفردوس الأعلى هو أوسط الجنة وأعلاها وأفضلها، وفوقه عرش الرحمن جل جلاله، ومنه تتفجر أنهار الجنة الأربعة وتُغذى سائر الدرجات. وقد أمرنا النبي ﷺ بالهمة العالية في الدعاء، فقال: «إذا سألتم الله فاسألوه الفردوس».',
        e: 'صحيح البخاري (2790)',
        t: ['الفردوس', 'أعلى الجنة', 'عرش الرحمن', 'الدعاء', 'الجنة'],
      ),
      (
        q: 'كم عدد أبواب الجنة وما أسماؤها؟',
        a: 'للجنة ثمانية أبواب عظيمة، أشهرها المذكور في النصوص الصحيحة: باب الصلاة، وباب الجهاد، وباب الريان (للصائمين)، وباب الصدقة، وباب الكاظمين الغيظ والعافين عن الناس، وباب الأيمن للمتوكلين بلا حساب، وباب الحج، وباب الراضين / الذكر والتوبة.',
        e: 'متفق عليه (البخاري 1897، مسلم 1027)',
        t: ['أبواب الجنة', 'باب الريان', 'باب الصلاة', 'باب الصدقة', 'ثمانية'],
      ),
      (
        q: 'ما مقدار سعة الباب الواحد من أبواب الجنة؟',
        a: 'أخبر النبي ﷺ أن ما بين مصراعي الباب الواحد من أبواب الجنة كما بين مكة وهجر، أو كما بين مكة وبُصرى بالشام (أكثر من ألف كيلومتر)، ومع ذلك يأتي عليه يوم وهو كظيظ من كثرة الزحام برحمة الله.',
        e: 'صحيح مسلم (194) وصحيح البخاري (4712)',
        t: ['سعة أبواب الجنة', 'الباب', 'مكة وهجر'],
      ),
      (
        q: 'كيف يُدعى المسلم من أبواب الجنة الثمانية كلها؟',
        a: 'من جمع بين أصول العبادات الخالصة: محافظ على الصلاة، مقبل على الصيام والتطوع، متصدق منفق، مستجيب لنصرة الحق، موحد متوكل، وكاظم للغيظ — كأبي بكر الصديق رضي الله عنه — ينادَى إكراماً له من جميع الأبواب.',
        e: 'صحيح البخاري (3666)',
        t: ['أبواب الجنة الثمانية', 'أبو بكر', 'الدخول'],
      ),
      (
        q: 'كيف يبني المسلم لنفسه قصراً في الجنة؟',
        a: 'أسهل طريق موثق لبناء قصر في الجنة هو قراءة سورة الإخلاص (قل هو الله أحد) عشر مرات كاملة، وكذلك بناء المساجد لوجه الله ولو كمفحص قطاة.',
        e: 'مسند أحمد (15610) والسلسلة الصحيحة (589)',
        t: ['قصر في الجنة', 'سورة الإخلاص', 'عشر مرات', 'بناء مسجد'],
      ),
      (
        q: 'كيف يبني المسلم بيتاً في الجنة كل يوم؟',
        a: 'من صلى لله تعالى اثنتي عشرة ركعة تطوعاً في يوم وليلة (غير الفريضة)، وهي السنن الرواتب: 4 قبل الظهر، و2 بعدها، و2 بعد المغرب، و2 بعد العشاء، و2 قبل الفجر — بنى الله له بيتاً في الجنة.',
        e: 'صحيح مسلم (728)',
        t: ['بيت في الجنة', 'السنن الرواتب', '12 ركعة'],
