        a: 'نعم؛ فقد أُدخل رجل الجنة بغصن شجرة قطعه من الطريق لكي لا يؤذي المسلمين، وغُفر لامرأة بسقيها كلباً يلهث من العطش، وتصدق رجل بشق تمرة فربّاها الله له حتى صارت مثل جبل أحد.',
        e: 'متفق عليه (البخاري 1410 و3467، مسلم 1914 و2245)',
        t: ['إماطة الأذى', 'الرحمة بالحيوان', 'شق تمرة'],
      ),
      (
        q: 'ما المقصود بالخيام والسرر والأرائك في الجنة؟',
        a: 'الأريكة هي السرير المزين المفروش تحت الحجلة (الستار الملكي)، والسرر موضوعة مرفوعة مبطنة بالذهب والياقوت متقابلة ليتآنس الجالسون ويتبادلوا الحديث الطيب بلا ملل.',
        e: 'سورة الغاشية (13-16) وسورة الرحمن (72)',
        t: ['الأرائك', 'السرر', 'الرفاهية'],
      ),
      (
        q: 'هل يُقارن نعيم الدنيا كله بما في الجنة؟',
        a: 'أقسم النبي ﷺ أن موضع سوط (قدر متر واحد) في الجنة خير من الدنيا وما فيها من قصور وكنوز وزخارف؛ فما بالكم بالملك الكبير الذي يعطيه الله لأهل الفردوس!',
        e: 'صحيح البخاري (3250)',
        t: ['موضع سوط', 'قيمة الدنيا', 'الآخرة'],
      ),
      (
        q: 'ما جزاء الصابرين على فقد الولد أو البصر في الدنيا؟',
        a: 'من ابتُلي بفقد حبيبته (عينيه) فصبر واحتسب لم يرضَ الله له ثواباً دون الجنة، ومن مات له ولد أو فرط صبر عليه وحمد الله واسترجع بنى الله له بيتاً في الجنة وسماه «بيت الحمد».',
        e: 'صحيح البخاري (5653) وسنن الترمذي (1021)',
        t: ['بيت الحمد', 'الصبر على الابتلاء', 'فقد البصر'],
      ),
      (
        q: 'ما أجمع دعاء لطلب الجنة والاستعاذة من النار؟',
        a: 'قولك بقلب موقن: «اللهم إني أسألك الجنة وأعوذ بك من النار» ثلاث مرات؛ فإذا قلتها قالت الجنة: اللهم أدخله الجنة، وإذا استجرت من النار قالت النار: اللهم أجره من النار، وأفضل صيغها النبوية: «اللهم إني أسألك الفردوس الأعلى وما قرّب إليه من قول أو عمل».',
        e: 'سنن الترمذي (2572) وابن ماجه (3846)',
        t: ['الدعاء بالجنة', 'اللهم إني أسألك الجنة', 'الاستعاذة من النار'],
      ),
    ]);

    // =========================================================================
    // 2. العقيدة والإيمان واليوم الآخر (51 - 100)
    // =========================================================================
    addCategory(IslamicQaCategory.aqeedah, [
      (
        q: 'ما هي أركان الإسلام الخمسة وما أركان الإيمان الستة؟',
        a: 'أركان الإسلام: شهادة أن لا إله إلا الله وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت لمن استطاع إليه سبيلاً. وأركان الإيمان: أن تؤمن بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وبالقدر خيره وشره.',
        e: 'حديث جبريل في صحيح مسلم (8)',
        t: ['أركان الإسلام', 'أركان الإيمان', 'العقيدة'],
      ),
      (
        q: 'ما معنى لا إله إلا الله على التحقيق؟',
        a: 'معناها: لا معبود بحق إلا الله؛ فهي تتضمن النفي لجميع المعبودات من دون الله، والإثبات الكامل للعبادة بكل أنواعها (كالدعاء والتوكل والذبح والاستعانة والصلاة) لله وحده لا شريك له.',
        e: 'سورة محمد (19) وسورة الحج (62)',
        t: ['التوحيد', 'لا إله إلا الله', 'معنى الشهادة'],
