        a: 'الإحسان هو أعلى مراتب الدين؛ وقد عرّفه النبي ﷺ بقوله: «أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك»، ويثمر خشية ومراقبة وإتقاناً في العمل والمعاملات.',
        e: 'متفق عليه (حديث جبريل)',
        t: ['الإحسان', 'مراقبة الله', 'المراتب'],
      ),
      (
        q: 'أين الله تعالى وكيف يصفه المسلم؟',
        a: 'الله تعالى مستوٍ على عرشه فوق السماوات السبع استواءً يليق بجلاله وعظمته دون تشبيه أو تكييف، وهو سبحانه معنا بعلمه وسمعه وبصره وإحاطته في كل مكان، ليس كمثله شيء وهو السميع البصير.',
        e: 'سورة الشورى (11) وسورة طه (5)',
        t: ['أين الله', 'الاستواء', 'الأسماء والصفات'],
      ),
      (
        q: 'ما فضل حفظ أسماء الله الحسنى والعمل بها؟',
        a: 'قال ﷺ: «إن لله تسعة وتسعين اسماً، مائة إلا واحداً، من أحصاها دخل الجنة»؛ والإحصاء يشمل حفظ ألفاظها، وفهم معانيها، ودعاء الله بها، والتعبد بمقتضاها (كالتوكل على الوكيل، ورجاء الغفور، والرحمة تأسياً بالرحيم).',
        e: 'متفق عليه (البخاري 2736، مسلم 2677)',
        t: ['أسماء الله الحسنى', '99 اسم', 'دخل الجنة'],
      ),
      (
        q: 'ما حكم التشاؤم أو التفاؤل والطيرة في الإسلام؟',
        a: 'التشاؤم بالأيام أو الأرقام أو الطيور أو الألوان (كالتشاؤم بشهر صفر أو الغراب أو يوم الأربعاء) من بقايا الجاهلية وهو محرم ومنقص للتوحيد، أما التفاؤل بالكلمة الطيبة فكان يعجب النبي ﷺ ويحبه.',
        e: 'متفق عليه (البخاري 5756، مسلم 2224)',
        t: ['التشاؤم', 'التفاؤل', 'الطيرة'],
      ),
      (
        q: 'ما حكم قراءة الأبراج والكف والفنجان والسحر والكهانة؟',
        a: 'كلها محرمة ولا يجوز تصديقها لأن علم الغيب مما استأثر الله به وحده، ومن أتى عرافاً أو كاهناً فسأله لم تُقبل له صلاة أربعين يوماً، فإن صدقه بما يقول فقد كفر بما أنزل على محمد ﷺ.',
        e: 'صحيح مسلم (2230) وسنن أبي داود (3904)',
        t: ['الأبراج', 'الفنجان', 'العراف', 'السحر', 'الغيب'],
      ),
      (
