        a: 'الإيمان بالقدر يعني اليقين بأن الله علم كل شيء وكتبه في اللوح المحفوظ وشاءه وخلقه، مع إثبات أن للعبد إرادة واختياراً يُحاسب عليهما، وأن الشرع يأمر بالأخذ بالأسباب ثم التوكل على الله لا التواكل والجلوس.',
        e: 'صحيح مسلم (2664 - احرص على ما ينفعك واستعن بالله)',
        t: ['القضاء والقدر', 'الأخذ بالأسباب', 'التوكل'],
      ),
      (
        q: 'هل الدعاء يرد القدر؟',
        a: 'نعم؛ فقد ورد في الحديث: «لا يرد القضاء إلا الدعاء»، والمعنى أن الله قدّر أن يدفع البلاء بقدرِ آخر وهو الدعاء الموفق الذي ييسره للعبد؛ فالدعاء والأخذ بالأسباب نفسها من جملة قدر الله.',
