        a: 'القبر أول منازل الآخرة، وهو إما روضة من رياض الجنة أو حفرة من حفر النار. وفيه يُسأل الميت من مَلَكَين (منكر ونكير) ثلاثة أسئلة مصيرية: من ربك؟ ما دينك؟ من نبيك؟ ويثبت الله الذين آمنوا بالقول الثابت.',
        e: 'صحيح البخاري (1338) وسورة إبراهيم (27)',
        t: ['القبر', 'فتنة القبر', 'عذاب القبر', 'منكر ونكير'],
