        a: 'بعد البعث والحساب توضع أعمال العباد وأقوالهم في ميزان حقيقي له كفتان؛ فتُوزن الحسنات والسيئات بدقة وعدل لا يُظلم فيه أحد مثقال ذرة، ثم يأخذ كل إنسان كتابه إما بيمينه فينجو ويفرح، وإما بشماله أو وراء ظهره.',
        e: 'سورة الأنبياء (47) وسورة الانشقاق (7-12)',
        t: ['الميزان', 'الحساب', 'تطاير الصحف', 'يوم القيامة'],
      ),
      (
        q: 'ما هو الصراط ومن يعبره؟',
        a: 'الصراط جسر ممدود على متن جهنم يعبره جميع الناس بعد الحساب على قدر أعمالهم ونور إيمانهم؛ فمنهم من يمر كالبرق، وكالريح، وكالفرس الجواد، ومنهم من يزحف زحفاً، وأكثر ما ينفع العبد فيه أمانته وصلة رحمه وصبره.',
