        a: 'استعذ بالله من الشيطان الرجيم، وانتهِ عن الاسترسال في الفكر، وقل: «آمنت بالله ورسله»، واعلم أن كراهتك لهذه الوساوس وضيق صدرك بها هو صريح الإيمان ودليل على أن الشيطان عجز أن يفسد قلبك.',
