        e: 'متفق عليه (البخاري 660، مسلم 1031)',
        t: ['السبعة الذين يظلهم الله', 'الشباب', 'المساجد', 'الصدقة'],
      ),
      (
        q: 'هل نرى الملائكة أو الشياطين ولماذا خُلقت الملائكة؟',
        a: 'الملائكة خلق عظيم من نور لا يعصون الله ما أمرهم ويفعلون ما يؤمرون؛ منهم جبريل للوحي، وميكائيل للقطر والرزق، وإسرافيل للصور، وملك الموت، والكرام الكاتبون والحفظة الذين يرافقون الإنسان؛ ولا نراهم في هيئتهم الأصلية عادة إكراماً لحال الدنيا والاختبار.',
