        t: ['الملائكة', 'جبريل', 'الحفظة'],
      ),
      (
        q: 'ما الموقف الشرعي الصحيح تجاه الجن والحسد والعين؟',
        a: 'العين حق ولها أثر بإذن الله كما ثبت في الصحيح، وكذلك السحر والجن مخلوقات موجودة، لكنها كلها تحت قدرة الله لا تضر أحداً إلا بإذنه؛ وحصن المسلم الحقيقي هو المحافظة على الصلوات في وقتها وأذكار الصباح والمساء وآية الكرسي والمعوذتين دون مبالغة أو وسوسة مرضية.',
