        e: 'سورة الممتحنة (آية 8)',
        t: ['الولاء والبراء', 'التعايش', 'العدل مع غير المسلمين'],
      ),
      (
        q: 'ما الفرق بين القضاء المبرم والقضاء المعلق؟',
        a: 'علم الله الأزلي الذي في أم الكتاب لا يتبدل ولا يتغير (وهو المبرم)، أما ما يكتب في صحف الملائكة من الأعمار والأرزاق فإنه يُعلق أحياناً بأسباب جعلها الله، كصلة الرحم التي تبسط في الرزق وتنسأ في الأثر، والدعاء الذي يرد البلاء بإذن الله.',
        e: 'صحيح البخاري (2067) وسورة الرعد (39)',
        t: ['الرزق', 'صلة الرحم', 'يمحو الله ما يشاء'],
      ),
      (
        q: 'لماذا يصيب الله المؤمنين الصالحين بالبلاء أحياناً؟',
        a: 'الابتلاء علامة رحمة واختبار للمؤمن: إما ليكفر الله به من خطاياه حتى يلقاه نقياً، أو ليرفعه درجة لم يكن يبلغها بعمله وحده، أو ليزيد من صبره وتضرعه ولجوئه إلى الله، ولا يكون عقوبة على الصابر الراضي.',
        e: 'سنن الترمذي (2398) وصحيح البخاري (5641)',
        t: ['البلاء', 'الصبر', 'رفع الدرجات', 'المصيبة'],
      ),
      (
        q: 'ما حكم الاحتجاج بالقدر عند فعل المعاصي؟',
        a: 'الاحتجاج بالقدر على فعل المعصية باطل شرعاً وعقلاً؛ لأن الإنسان يعمل باختياره ولا يدري ما قُدّر له حتى يفعله، وإنما يُحتج بالقدر عند وقوع المصائب لتسلي النفس بالصبر والرضا، لا لتبرير الذنوب.',
        e: 'سورة الأنعام (148)',
