    // =========================================================================
    // 4. الصلاة والخشوع والفوائت والسهو (151 - 200)
    // =========================================================================
    addCategory(IslamicQaCategory.prayer, [
      (
        q: 'ما هي أركان الصلاة التي لا تسقط عمداً ولا سهواً؟',
        a: 'أهم أركان الصلاة 14: القيام مع القدرة، وتكبيرة الإحرام، وقراءة الفاتحة، والركوع، والرفع منه، والسجود على الأعضاء السبعة، والرفع منه، والجلوس بين السجدتين، والطمأنينة في كل الأركان، والترتيب، والتشهد الأخير، والجلوس له، والصلاة على النبي ﷺ فيه، والتسليمتان (أو الأولى للخروج).',
        e: 'صحيح البخاري (757 - حديث المسيء صلاته)',
        t: ['أركان الصلاة', 'الفاتحة', 'الطمأنينة'],
      ),
      (
        q: 'ما حكم من فاتته صلوات كثيرة من سنين هل يقضيها أم تكفيه التوبة؟',
        a: 'على مذهب جمهور الأئمة الأربعة يجب قضاء الصلوات الفائتة التي تعمد تركها أو نسيها بحسب طاقته (كأن يصلي مع كل فرض حاضراً صلاةً أو صلاتين قضاءً في سجل الفوائت)، وقال ابن تيمية بوجوب التوبة النصوح والإكثار من النوافل لمن تركها عمداً دهراً؛ والجمع بين التوبة وقضاء ما أمكن من الفوائت في سجل الفردوس هو الأحوط والأبرأ للذمة.',
        e: 'متفق عليه (من نام عن صلاة أو نسيها فليصلها إذا ذكرها) والمغني',
        t: ['قضاء الصلوات', 'الفوائت', 'تارك الصلاة', 'صلوات قديمة'],
      ),
      (
        q: 'كيف أقضي الصلوات التي فاتتني في اليوم بترتيب صحيح؟',
        a: 'إذا ذكرت فائتة في يومك (كالظهر وتذكرتها وقت العصر)، صلِّ الفائتة أولاً ثم الحاضرة للترتيب ما لم يضق وقت الحاضرة جداً، وإن نسيت الترتيب أو خشيت فوات جماعة الحاضرة فصلِّ الحاضرة ثم اقضِ الفائتة بعدها مباشرة.',
        e: 'صحيح البخاري (597) وسنن النسائي',
        t: ['الترتيب في القضاء', 'صلاة فائتة'],
      ),
      (
        q: 'متى يُسجد سجود السهو: قبل السلام أم بعده؟',
        a: 'ملخص هديه ﷺ يسر وسهل: إذا سها عن نقص في الصلاة (كنسيان التشهد الأول أو الشك وبنيت على الأقل اليقيني) تسجد سجدتين للسهو **قبل السلام**؛ وإذا سها بالزيادة (كزاد ركعة أو سجدتين أو سلم قبل تمام صلاته وتنبه ثم أتمها وبنى على غالب الظن) تسجد للسهو **بعد السلام**؛ وكلاهما مجزئ ومشروع ولا يبطل الصلاة إن عُكس.',
        e: 'متفق عليه (البخاري 1225، مسلم 570)',
        t: ['سجود السهو', 'قبل السلام', 'بعد السلام'],
      ),
      (
        q: 'ماذا أفعل إذا شككت هل صليت ثلاث ركعات أم أربعاً؟',
        a: 'إذا كان شكاً عرضياً وليس وسواساً مرضياً، فاطرح الشك وابنِ على الأقل المتيقن (أي اجعلها ثلاثاً)، وأتِ بالرابعة، ثم اسجد سجدتين للسهو قبل أن تسلم؛ وإن كنت صاحب وسواس متكرر فلا تلتفت للشك أبداً!',
        e: 'صحيح مسلم (571)',
        t: ['الشك في عدد الركعات', 'نسيت كم صليت'],
