        a: 'بعد صلاة الفجر حتى تطلع الشمس وترتفع قدر رمح (نحو 15-20 دقيقة بعد الشروق)، وعند استواء الشمس قبيل أذان الظهر بدقائق (نحو 5-10 دقائق)، وبعد صلاة العصر حتى تغرب الشمس. أما الصلوات ذات السبب (كقضاء الفائتة أو تحية المسجد أو سنة الوضوء أو الاستخارة الضرورية) فتُصلّى في كل وقت على الراجح.',
