        q: 'ما حكم تأخير صلاة العشاء إلى منتصف الليل وهل ينقضي وقتها؟',
        a: 'يمتد وقت صلاة العشاء الاختياري إلى منتصف الليل الشرعي (وهو منتصف المسافة الزمنية بين المغرب والفجر، ويظهر لك دقيقاً في تطبيق الفردوس!) ولا ينبغي تأخيرها لغير عذر بعد ذلك، ومن صلاها قبل أذان الفجر لعذر أو نوم فليؤدها فوراً.',
        e: 'صحيح مسلم (612)',
        t: ['وقت العشاء', 'منتصف الليل الشرعي'],
      ),
      (
        q: 'متى يبدأ وقت صلاة الضحى ومتى ينتهي وكم ركعاتها؟',
        a: 'يبدأ وقت صلاة الضحى بعد ارتفاع الشمس قدر رمح (بعد الشروق بنحو 15-20 دقيقة تقريباً كما يحسبه لك تطبيق الفردوس)، وينتهي قبل زوال الشمس وأذان الظهر بنحو 10 دقائق؛ وأقلها ركعتان وأكثرها ثمانٍ أو أكثر مثنى مثنى، وأفضل أوقاتها حين يشتد الحر وترمض الفصال.',
