      (
        q: 'ما هي مواضع وضع اليدين والرفع في الصلاة؟',
        a: 'يُسن رفع اليدين حذو المنكبين أو الأذنين في أربعة مواضع فقط: عند تكبيرة الإحرام، وعند الركوع، وعند الرفع من الركوع، وعند القيام من التشهد الأول للثالثة؛ ويقبض يده اليمنى على اليسرى على صدره أو أسفله بقليل بتواضع.',
        e: 'صحيح البخاري (735 و739)',
