      (
        q: 'ما حكم تغطية القدمين للمرأة في الصلاة وكيف تلبس الحجاب فيها؟',
        a: 'يجب أن تستر المرأة في صلاتها جسدها كله سوى الوجه والكفين (ويجوز في البيت إذا لم يكن أجانب)، أما القدمين فجمهور الأئمة على وجوب سترهما بثوب طويل أو جورب احتياطاً لصحة الصلاة، إلا عند الحنفية، فالستر بالجورب أو الإسدال الطويل أبرأ وأحوط.',
        e: 'سنن أبي داود (641) والموسوعة الفقهية',
        t: ['صلاة المرأة', 'غطاء القدمين', 'الحجاب في الصلاة'],
      ),
      (
        q: 'هل يفسد الصلاة الالتفات اليسير بالبصر أو البكاء أو الحركة الخفيفة لحاجة؟',
        a: 'تثبيت البصر نحو موضع السجود هو السنة، والالتفات اليسير عند الحاجة أو تسوية الغترة أو حمل الطفل في الصلاة لا يبطلها (فقد صلى النبي ﷺ حاملاً أمامة)، والأنين والبكاء من خشية الله يزيدها نوراً لا يبطلها، إنما تبطل بالحركات الكثيرة المتوالية العبثية لغير ضرورة.',
        e: 'متفق عليه (البخاري 516، مسلم 543)',
