        a: 'قال ﷺ لعمران بن حصين: «صلِّ قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب»؛ فإن عجزت عن الركوع والسجود أومأت برأسك فيكون إيماؤك بالسجود أخفض من الركوع، وإن صليت على كرسي تريحك فصلِّ مع الجماعة ولك الأجر كاملاً بإذن الله.',
