      (
        q: 'ما حكم الأذان للمرأة وهل لها إقامة؟',
        a: 'الأذان والإقامة للصلوات الجهرية من خصائص الرجال في المساجد ولا يجبان على النساء؛ ولو أقامت المرأة لنفسها سراً في بيتها فلا حرج فيه وهو جائز على قول جماعة من الفقهاء.',
        e: 'المجموع وسنن البيهقي',
        t: ['أذان المرأة', 'إقامة المرأة'],
