      (
        q: 'كيف يصلي من ركبه الطائرة أو القطار أو السفينة وحان وقت الصلاة؟',
        a: 'إن خشي خروج الوقت قبل الوصول صلّى على حاله في المركب باتجاه القبلة إن استطاع الوقوف (كما هو في الطائرة والقطار)، وإن لم يتمكن من القيام أو التوجه للقبلة صلّى جالساً إلى جهة المسير ولا إثم عليه وتُقبل صلاته ولا يجب إعادة الفريضة عند تمام الشروط بالاستطاعة.',
        e: 'سورة التغابن (16) - فاتقوا الله ما استطعتم',
        t: ['الصلاة في الطائرة', 'القطار', 'السفر'],
      ),
