        q: 'ما حكم صيام يوم الشك (30 شعبان) أو صيام يوم الجمعة منفرداً؟',
        a: 'يُنهى عن صيام يوم الشك (آخر يوم في شعبان قبل ثبوت الهلال) إلا لمن وافق صوماً كان يصومه كالإثنين والخميس؛ ويُكره صوم يوم الجمعة وحده إلا أن يصوم قبله الخميس أو بعده السبت أو يوافق يوم عرفة أو عاشوراء.',
        e: 'متفق عليه (البخاري 1914 و1985، مسلم 1082 و1144)',
        t: ['يوم الشك', 'صوم الجمعة منفرداً'],
      ),
      (
        q: 'كيف نفهم فضل عشر ذي الحجة مقارنة بالعشر الأواخر من رمضان؟',
        a: 'أيام عشر ذي الحجة الأولى هي أفضل أيام الدنيا في العمل الصالح من تكبير وصيام وصدقة وحج وأضحية (لتنوع العبادات الجليلة فيها ووجود عرفة والنحر)؛ أما ليالي العشر الأواخر من رمضان فهي أفضل الليالي في الوجود لأن فيها ليلة القدر خير من ألف شهر!',
        e: 'صحيح البخاري (969) وزاد المعاد لابن القيم',
        t: ['عشر ذي الحجة', 'رمضان', 'مقارنة'],
      ),
      (
        q: 'ما حكم الأضحية وهل تجزئ شاة واحدة عن الأسرة كلها؟',
        a: 'الأضحية سنة مؤكدة جداً لمن قدر عليها في أيام العيد (أو واجبة عند الحنفية)، وتجزئ الشاة الواحدة (من الضأن أو الماعز) عن الرجل وأهل بيته كلهم ولو كثر عددهم؛ والبدنة أو البقرة تجزئ عن سبعة أشخاص وأسرهم.',
        e: 'صحيح مسلم (1967) وسنن الترمذي (1505)',
        t: ['الأضحية', 'العيد', 'الشاة'],
      ),
      (
        q: 'ما هي سنن المضحي في العشر الأول من ذي الحجة؟',
        a: 'إذا دخل شهر ذي الحجة وأراد المسلم أن يضحي، يُشرع له ألا يأخذ من شعره ولا أظافره شيئاً حتى يذبح أضحيته، وهذا مستحب للرجل والمرأة المضحيين تشبهاً بالمحرمين، ولا يبطل الأضحية إن قص لجهل أو نسيان.',
        e: 'صحيح مسلم (1977)',
        t: ['المضحي', 'الأظافر والشعر', 'ذي الحجة'],
      ),
      (
        q: 'ما حكم طواف الوداع عند السفر السريع من مكة؟',
        a: 'طواف الوداع واجب على الحاج عند خروجه من مكة (ما عدا الحائض والنفساء فيسقط عنهما تخفيفاً)؛ وأما في العمرة فمستحب استحباباً ولا يجب إن تعجل السفر، ولو كان طواف العمرة أو الحج آخر عهده بالبيت كفى.',
        e: 'متفق عليه (البخاري 1755، مسلم 1328)',
        t: ['طواف الوداع', 'العمرة والحج'],
      ),
      (
        q: 'هل يجب تقبيل الحجر الأسود في الزحام الشديد؟',
        a: 'تقبيل الحجر الأسود سنة وليس بواجب! وإيذاء المسلمين ومزاحمة النساء والضعفاء في الزحام محرم؛ فإذا اشتد الزحام فالسنة أن تشير إليه من بعيد بيدك اليمنى وتقول «الله أكبر» وتمضي بسكينة ورفق كما أرشد النبي ﷺ عمر بن الخطاب.',
        e: 'صحيح مسلم (1272) ومسند أحمد',
        t: ['الحجر الأسود', 'الزحام في الطواف'],
      ),
      (
        q: 'ما حكم الصدقة عن النفس سراً مقابل إظهارها للتشجيع؟',
        a: 'صدقة السر تطفئ غضب الرب وهي الأفضل غالباً لسلامة الإخلاص وحفظ ماء وجه الفقير؛ وتجوز الصدقة العلنية أحياناً إذا قُصد بها تربية الأبناء أو تشجيع الناس على التبرع لمشروع خيري مع مجاهدة الرياء.',
        e: 'سورة البقرة (271)',
        t: ['صدقة السر', 'العلانية', 'الرياء'],
      ),
      (
        q: 'هل على القروض الدينية أو الأرباح البنكية والأسهم زكاة؟',
        a: 'الأسهم التجارية المعدة للمضاربة والبيع تزكى على قيمتها السوقية بالكامل (2.5%) عند حولان الحول؛ أما الأسهم الاحتفاظية (للعائد السنوي) فيزكى الوعاء النقدي والأرباح الصافية في الشركات الصناعية إن لم تخرج الشركة زكاتها.',
        e: 'قرارات مجمع الفقه الإسلامي في زكاة الأسهم',
        t: ['زكاة الأسهم', 'الاستثمار', 'التجارة'],
      ),
      (
        q: 'ماذا يقول الصائم عند إفطاره؟',
        a: 'الذكر الثابت الصحيح عند الإفطار بعد غروب الشمس: «ذهب الظمأ وابتلت العروق وثبت الأجر إن شاء الله»، مع الإكثار من الدعاء الصادق قبيل الإفطار لأن للصائم عند فطره دعوة لا ترد.',
        e: 'سنن أبي داود (2357) وسنن ابن ماجه',
        t: ['دعاء الإفطار', 'ذهب الظمأ'],
      ),
      (
        q: 'هل يصح الصيام بالماء فقط في السحور مع ترك الغداء؟',
        a: 'نعم يصح الصوم بدون سحور أصلاً، وأفضل السحور على التمر أو جرعة ماء لنيل بركة السنة وإعانة البدن على النهار والطاعة.',
        e: 'سنن أبي داود (2345 - نعم سحور المؤمن التمر)',
        t: ['السحور على التمر', 'ترك السحور'],
      ),
      (
        q: 'ما أثر الاستغلال الأمثل لعشر ذي الحجة بالذكر؟',
        a: 'الإكثار من التكبير والتهليل والتحميد في البيوت والطرق والأسواق («الله أكبر الله أكبر لا إله إلا الله...») سنة مهجورة يغفل عنها كثير من الناس في العشر، تملأ الأرجاء تعظيماً لله ومضاعفة للحسنات.',
        e: 'صحيح البخاري معلقاً (كان ابن عمر وأبو هريرة يخرجان في أيام العشر فيكبران)',
        t: ['التكبير', 'عشر ذي الحجة'],
      ),
    ]);

    // =========================================================================
    // 7. الأذكار والدعاء والرقية والرؤى (301 - 350)
    // =========================================================================
    addCategory(IslamicQaCategory.dhikrDua, [
      (
        q: 'ما هي أوقات إجابة الدعاء الذهبية التي لا ينبغي تفويتها؟',
        a: 'الثلث الأخير من الليل وقت السحر، وأثناء السجود في الصلاة، وبين الأذان والإقامة، وآخر ساعة بعد عصر الجمعة قبل المغرب، وعند نزول المطر، وحال الصيام وعند الإفطار، وفي السفر، ودعوة المسلم لأخيه بظهر الغيب.',
        e: 'متفق عليه وسنن أبي داود والترمذي',
        t: ['إجابة الدعاء', 'ساعة الاستجابة', 'أوقات الدعاء'],
      ),
      (
        q: 'ما سبب تأخر إجابة الدعاء رغم أنني أدعو بإلحاح؟',
        a: 'لا يضيع الدعاء عند الله أبداً! فما من مسلم يدعو بدعوة ليس فيها إثم ولا قطيعة إلا أعطاه الله بها إحدى ثلاث: إما يعجل له دعوته، وإما يصرف عنه من السوء مثلها، وإما يدخرها له أجراً مضاعفاً في الجنة! ومن موانع الإجابة أكل الحرام والاستعجال وترك اليقين.',
        e: 'مسند أحمد (11133) وصحيح مسلم (2735)',
        t: ['تأخر الدعاء', 'لا يستجيب', 'آداب الدعاء'],
      ),
      (
        q: 'كيف يبدأ المسلم دعاءه وكيف يختمه ليكون أقرب للقبول؟',
        a: 'يبدأ بالثناء على الله وتمجيده (مثل: اللهم لك الحمد كما ينبغي لجلال وجهك، يا حي يا قيوم، اللهم إني أسألك بأني أشهد أنك أنت الله الأحد الصمد...)، ثم يصلي على النبي ﷺ، ثم يسأل حاجاته بيقين وحضور قلب وإلحاح، ثم يختم بالصلاة على النبي ﷺ.',
        e: 'سنن أبي داود (1481 و1493) والترمذي',
        t: ['آداب الدعاء', 'الصلاة على النبي في الدعاء', 'الاسم الأعظم'],
      ),
      (
        q: 'ما أفضل وقت لأذكار الصباح وأذكار المساء؟',
        a: 'أذكار الصباح الأفضل أن تُقرأ بعد صلاة الفجر إلى طلوع الشمس ويمتد وقتها لمن نسي حتى الزوال؛ وأذكار المساء من بعد صلاة العصر إلى المغرب ويمتد وقتها لمن شغل إلى ثلث الليل. وهي الحصن الحصين للمؤمن كل يوم.',
        e: 'حصن المسلم وفتاوى اللجنة',
        t: ['وقت أذكار الصباح', 'وقت أذكار المساء'],
      ),
      (
        q: 'ما هي الكلمات الأربع التي هي أحب الكلام إلى الله؟',
        a: 'قولك بتدبر ويقين: «سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر» لا يضرك بأيهن بدأت؛ وهي أحب إلى النبي ﷺ مما طلعت عليه الشمس وتغرس أربع أشجار في الجنة.',
        e: 'صحيح مسلم (2137 و2695)',
        t: ['أحب الكلام إلى الله', 'الباقيات الصالحات'],
      ),
      (
        q: 'ما هي الكلمتان الخفيفتان على اللسان الثقيلتان في الميزان؟',
        a: '«سبحان الله وبحمده، سبحان الله العظيم»؛ كلمتان يسيرتان على كل لسان ولكنهما حبيبتان إلى الرحمن وترجحان بميزان الأعمال يوم القيامة.',
        e: 'متفق عليه (البخاري 6406، مسلم 2694)',
        t: ['خفيفتان على اللسان', 'سبحان الله وبحمده', 'الميزان'],
      ),
      (
        q: 'ما هي صيغة الصلاة الإبراهيمية وأفضل صيغ الصلاة على النبي ﷺ؟',
        a: 'أكملها ما نقولها في التشهد: «اللهم صلِّ على محمد وعلى آل محمد، كما صليت على إبراهيم وعلى آل إبراهيم، إنك حميد مجيد؛ اللهم بارك على محمد وعلى آل محمد، كما باركت على إبراهيم وعلى آل إبراهيم، إنك حميد مجيد». وأقصرها: «اللهم صل وسلم على نبينا محمد».',
        e: 'متفق عليه (البخاري 3370)',
        t: ['الصلاة الإبراهيمية', 'الصلاة على النبي'],
      ),
      (
        q: 'ما ثمرة الإكثار من الصلاة على النبي ﷺ في تفريج الهموم؟',
        a: 'قال الصحابي أُبي بن كعب: أجعل لك صلاتي (دعائي) كلها؟ فقال ﷺ: «إذاً تُكفى همك، ويُغفر ذنبك»؛ فهي مفتاح عظيم لانشراح الصدر وغفران الذنوب واستجابة الدعوات.',
        e: 'سنن الترمذي (2457)',
        t: ['تُكفى همك', 'الصلاة على النبي', 'الهموم'],
      ),
      (
        q: 'هل يجوز التسبيح بالخاتم الإلكتروني أو المسبحة الخرزية أو في التطبيق؟',
        a: 'نعم جائز مباح لعدّ الأذكار المقيدة بأعداد (كـ 33 أو 100)، كالسبحة التفاعلية في تطبيق الفردوس أو الخاتم؛ مع كون العد بأصابع اليد اليمنى هو الأفضل عند التيسر لأن الأصابع مستنطقات تشهد يوم القيامة، ولا تضاد بين الأمرين.',
        e: 'سنن أبي داود (1501) ومجموع فتاوى ابن تيمية',
        t: ['السبحة', 'السبحة الإلكترونية', 'التسبيح بالأصابع'],
      ),
      (
        q: 'ما هي الشروط الثلاثة ليكون الرقية الشرعية جائزة ومؤثرة؟',
        a: '1- أن تكون بكلام الله (القرآن) أو أسمائه وصفاته والأدعية النبوية المأثورة؛ 2- أن تكون باللسان العربي الفصيح المفهوم المعنى بلا طلاسم ولا أسماء غريبة؛ 3- أن يعتقد الراقي والمرقي أن الرقية سبب فقط وأن الشافي هو الله وحده لا غيره.',
        e: 'صحيح مسلم (2200) وفتح الباري',
        t: ['الرقية الشرعية', 'شروط الرقية', 'الحسد والسحر'],
      ),
      (
        q: 'هل يجوز أن يرقي الإنسان نفسه أم لا بد أن يذهب لشيخ راقٍ؟',
        a: 'رقية الإنسان لنفسه ولأهله وأولاده هي الأفضل والأقوى والأكثر بركة وصدقاً واضطراراً لله، وبذلك يظفر بصفة المتوكلين الذين لا يطلبون الرقية من الغير؛ فيقرأ الفاتحة وآية الكرسي وخواتيم البقرة والمعوذات مع النفث ومسح موضع الألم بيده.',
        e: 'متفق عليه وصحيح مسلم (2202)',
        t: ['رقية النفس', 'الشفاء'],
      ),
      (
        q: 'ما الدعاء المأثور عند الشعور بألم في الجسد أو المرض؟',
        a: 'تضع يدك على موضع الألم من جسدك وتقول: «بسم الله» ثلاثاً، ثم تقول سبع مرات: «أعوذ بالله وقدرته من شر ما أجد وأحاذر»، وتردد الفاتحة سبع مرات فهي الرقية العظمى.',
        e: 'صحيح مسلم (2202)',
        t: ['دعاء الألم', 'علاج المرض بالذكر'],
      ),
      (
        q: 'ما حكم الحروز والتمائم والخرزة الزرقاء وعين الحاسد؟',
        a: 'تعليق التمائم والخرزة الزرقاء والكف المعلقة في البيوت والسيارات لدفع العين محرم ومنكر عظيم لا يجوز للمسلم فعله؛ «من علق تميمة فلا أتم الله له»؛ فالحافظ هو الله وحده وتُعلق القلوب به وبقراءة المعوذات.',
        e: 'مسند أحمد (17440) وسنن أبي داود (3883)',
        t: ['الخرزة الزرقاء', 'التمائم', 'الكف', 'الحسد'],
      ),
      (
        q: 'ماذا يفعل المسلم إذا رأى حلماً مزعجاً أو كابوساً في منامه؟',
        a: 'يستعيذ بالله من شر الشيطان وشر ما رأى ثلاث مرات، ويتفل عن يساره ثلاثاً نفثاً لطيفاً، ويتحول عن جنبه الذي كان عليه، ولا يحدّث أحداً بهذه الرؤيا السيئة أبداً، فإنها بإذن الله لن تضره شيئاً.',
        e: 'متفق عليه (البخاري 6985، مسلم 2261)',
        t: ['الكابوس', 'الحلم المزعج', 'الرؤيا'],
      ),
      (
        q: 'ما الفرق بين الرؤيا الصالحة وحلم الشيطان وحديث النفس؟',
        a: 'الرؤيا الصادقة من الله وغالباً تكون واضحة حسنة مبشرة (فيقصها المسلم على محب ناصح فقط)؛ وحلم الشيطان مخيف محزن مضطرب للتحزين (يدفعه ولا يخبر به)؛ وحديث النفس انعكاس لأفكار النهار ومشاغله في العقل الباطن ولا عبرة بتأويله.',
        e: 'صحيح مسلم (2263)',
        t: ['أنواع المنامات', 'تفسير الأحلام', 'الرؤيا الصالحة'],
      ),
      (
        q: 'ما معنى أن الشيطان قد ينفر من البيت ويفر منه؟',
        a: 'البيت الذي يُذكر الله فيه ويُصلى فيه وتُقرأ فيه سورة البقرة تعمره الملائكة وتهجره الشياطين؛ والبيت الذي يخلو من الصلاة وتلاوة القرآن يتحول لمأوى للوحشة والكآبة ونزغات الشياطين.',
        e: 'صحيح مسلم (779 و780)',
        t: ['سورة البقرة في البيت', 'طرد الشياطين'],
      ),
      (
        q: 'كيف نحمي الأطفال الصغار من العين والشرور؟',
        a: 'نعيذهم بكلمات النبي ﷺ التي كان يعيذ بها الحسن والحسين: تضع يدك على رأس الصبي وتقول: «أعيذكما بكلمات الله التامة، من كل شيطان وهامة، ومن كل عين لامة» صباحاً ومساءً مع قراءة المعوذات ومسح أجسادهم.',
        e: 'صحيح البخاري (3371)',
        t: ['تحصين الأطفال', 'العين على الأولاد'],
      ),
      (
        q: 'ما هي دعوة ذي النون (نبي الله يونس) عند الشدة والكرب؟',
        a: 'قوله عليه السلام في ظلمات البحر: «لا إله إلا أنت سبحانك إني كنت من الظالمين»؛ ما دعا بها رجل مسلم في شيء قط إلا استجاب الله له وفرج كربه كما فرج عن نبيه يونس.',
        e: 'سنن الترمذي (3505) وصحيح الجامع',
        t: ['دعوة ذي النون', 'يونس', 'الكرب'],
      ),
      (
        q: 'ما أفضل دعاء في الكرب العظيم والهم والغم والحزن؟',
        a: 'دعاء الكرب: «لا إله إلا الله العظيم الحليم، لا إله إلا الله رب العرش العظيم، لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم»، وكذلك دعاء: «اللهم إني عبدك ابن عبدك ابن أمتك ناصيتي بيدك... أن تجعل القرآن ربيع قلبي ونور صدري وجلاء حزني وذهاب همي».',
        e: 'متفق عليه ومسند أحمد (3712)',
        t: ['دعاء الهم والحزن', 'تفريج الكرب'],
      ),
      (
        q: 'ما هو الذكر الموعود لمن أراد قضاء الدين وتيسير الرزق؟',
        a: 'دعاء علمه النبي ﷺ لعلي بن أبي طالب لو كان عليك مثل جبل صبير ديناً أداه الله عنك: «اللهم اكفني بحلالك عن حرامك، وأغنني بفضلك عمن سواك»، مع قول: «اللهم إني أعوذ بك من الهم والحزن... وغلبة الدين وقهر الرجال» صباحاً ومساءً، والعمل الجاد.',
        e: 'سنن الترمذي (3563) وصحيح البخاري (6369)',
        t: ['قضاء الدين', 'الرزق', 'دعاء سداد الدين'],
      ),
      (
        q: 'ما دعاء الركوب ودعاء السفر؟',
        a: 'عند ركوب السيارة أو السفر تقول: «بسم الله، الحمد لله، سبحان الذي سخر لنا هذا وما كنا له مقرنين وإنا إلى ربنا لمنقلبون... اللهم إنا نسألك في سفرنا هذا البر والتقوى ومن العمل ما ترضى، اللهم هوّن علينا سفرنا هذا واطوِ عنا بعده».',
        e: 'صحيح مسلم (1342)',
        t: ['دعاء السفر', 'دعاء الركوب'],
      ),
      (
        q: 'ما أذكار الدخول والخروج من المنزل؟',
        a: 'عند الخروج: «بسم الله، توكلت على الله، ولا حول ولا قوة إلا بالله» (فيقال لك: هُديت وكُفيت ووُقيت وتنحى عنك الشيطان!). وعند الدخول تسلم على أهلك وتقول: «بسم الله ولجنا وبسم الله خرجنا وعلى ربنا توكلنا».',
        e: 'سنن أبي داود (5095 و5096)',
        t: ['دعاء الخروج من البيت', 'دعاء دخول البيت'],
      ),
      (
        q: 'ما حكم الدعاء الجماعي بعد الصلوات المكتوبة بصوت واحد كل صلاة؟',
        a: 'لم يكن من هدي النبي ﷺ أن يداوم بعد التسليم على الدعاء الجماعي برفع الأيدي بصوت موحد خلف الإمام في كل فريضة؛ وإنما كان يذكر الله بالأذكار الواردة ثم يدعو كل مصلٍّ ربه سراً لنفسه في السجود وقبل السلام وبعد الأذكار.',
        e: 'فتاوى الأئمة وزاد المعاد',
        t: ['الدعاء الجماعي', 'بعد الصلاة'],
      ),
      (
        q: 'ما حكم قراءة القرآن أو الرقية على الماء والزيت والشرب منها؟',
        a: 'مباح ولا بأس به وأجازه جماعة من السلف وكبار العلماء، كأن يقرأ المعوذات والفاتحة في كفيه أو قرب كوب ماء ويشرب منه المريض أو يغتسل به تيمناً ببركة كلام الله الممزوج بالاستشفاء مع بقاء الاعتقاد أن الشفاء بيد الله.',
        e: 'زاد المعاد وفتاوى اللجنة الدائمة',
        t: ['الماء المقروء عليه', 'الرقية بالماء'],
      ),
      (
        q: 'كيف يشكر المسلم الله عند سماع الرعد أو رؤية المطر أو الريح؟',
        a: 'عند المطر يقول: «اللهم صيباً نافعاً» ويدعو؛ وبعد المطر: «مُطرنا بفضل الله ورحمته». وعند الريح الشديدة: «اللهم إني أسألك خيرها وخير ما فيها...». وعند الرعد: «سبحان الذي يسبح الرعد بحمده والملائكة من خيفته».',
        e: 'صحيح البخاري وصحيح مسلم وموطأ مالك',
        t: ['دعاء المطر', 'الرعد', 'الرياح'],
      ),
      (
        q: 'ما الدعاء المأثور عند رؤية شخص مبتلى بمرض أو مصيبة؟',
        a: 'تقول في نفسك سراً لئلا تجرح مشاعر المريض أو المبتلى: «الحمد لله الذي عافاني مما ابتلاك به، وفضلني على كثير ممن خلق تفضيلاً»؛ فمن قالها عُوفي من ذلك البلاء ما عاش.',
        e: 'سنن الترمذي (3431)',
        t: ['رؤية مبتلى', 'شكر النعمة'],
      ),
      (
        q: 'هل يُشرع الدعاء على من ظلمني أم العفو عنه؟',
        a: 'يجوز للمظلوم أن يدعو على ظالمه بقدر مظلمته دون اعتداء أو شطط، والأعظم والأرفع درجة في الجنة أن يفوض أمره لله أو يعفو عنه إن أرجو صلاحه ويقول: «حسبنا الله ونعم الوكيل»، و«اللهم أجرني في مصيبتي وأخلف لي خيراً منها».',
        e: 'سورة الشورى (40) وصحيح البخاري',
        t: ['دعوة المظلوم', 'الظلم', 'العفو'],
      ),
      (
        q: 'ما هي كلمات «كفارة المجلس» ومتى تقال؟',
        a: 'تُقال عند نهاية أي اجتماع أو جلسة أو مكالمة هاتفية مع الأصدقاء: «سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك»؛ فتكون كفارة للغو الذي جرى في ذلك المجلس.',
        e: 'سنن الترمذي (3433) وأبي داود (4859)',
        t: ['كفارة المجلس', 'ختام المجالس'],
      ),
      (
        q: 'ما دعاء دخول السوق وما ثوابه العجيب؟',
        a: 'إذا دخلت السوق أو المول التجاري فاذكر الله الغافل عنه الناس وقل: «لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت وهو حي لا يموت، بيده الخير وهو على كل شيء قدير»؛ ففي حسن السند أنه يكتب لقائله ألف ألف حسنة ويمحى عنه مثلها في غفلة الأسواق.',
        e: 'سنن الترمذي (3428) وحسنه الألباني',
        t: ['دعاء السوق', 'ألف ألف حسنة'],
      ),
      (
        q: 'كيف ندعو للمريض عند زيارته؟',
        a: 'تطمئنه وتبشره ولا تخوفه، وتضع يدك بلطف وتقول: «لا بأس طهور إن شاء الله»، وتدعو سبع مرات: «أسأل الله العظيم رب العرش العظيم أن يشفيك»، فإذا قالها لغير من حضر أجله شفاه الله.',
        e: 'صحيح البخاري (3616) وأبي داود (3106)',
        t: ['زيارة المريض', 'دعاء الشفاء'],
      ),
      (
        q: 'ما أذكار ما بعد الفزع في النوم والقلق الليلي؟',
        a: 'تقول: «أعوذ بكلمات الله التامات من غضبه وعقابه وشر عباده، ومن همزات الشياطين وأن يحضرون»، مع التقلب والوضوء أو تلاوة آية الكرسي.',
        e: 'سنن الترمذي (3528)',
        t: ['الفزع في النوم', 'الأرق'],
      ),
      (
        q: 'ما فضل كلمة «لا حول ولا قوة إلا بالله» في علاج الكسل والهم؟',
        a: 'هي كلمة استعانة لا استرجاع! فعند التعب والهم والاختبار والمهمات الصعبة لا تعتمد على ذكائك وحدك، بل رددها بصدق مستشعراً أنك تستمد طاقتك وتوفيقك من القوي المتين فينطلق القلب بقوة عجيبة.',
        e: 'الفتاوى لابن تيمية في الحوقلة',
        t: ['الحوقلة', 'العجز والكسل'],
      ),
      (
        q: 'ما دعاء الزيادة في الرزق الحلال والبركة في الأولاد؟',
        a: '«اللهم بارك لي في أهلي ومالي»، «رب هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إماماً»، مع الاستغفار الدائم الذي يفتح أبواب السماء والأرزاق كما في سورة نوح.',
        e: 'سورة الفرقان (74) وسورة نوح (10-12)',
        t: ['دعاء الأبناء', 'البركة في الأهل', 'الذرية'],
      ),
      (
        q: 'هل يجب رفع اليدين عند الدعاء أم يصح بدونه؟',
        a: 'رفع اليدين في الدعاء العام من أسباب القبول والخشوع (لأن الله حيي كريم يستحيي إذا رفع عبده يديه أن يردهما صفراً)، ولا يُرفعان في الأدعية المقيدة بالصلاة إلا في قنوت الوتر والنوازل، أو عند خطبة الجمعة للاستسقاء؛ أما ما سوى ذلك فالأمر واسع في الخلوات.',
        e: 'سنن أبي داود (1488)',
        t: ['رفع اليدين في الدعاء', 'الحياء الإلهي'],
      ),
      (
        q: 'ما الدعاء المأثور عند رؤية الهلال الجديد لكل شهر؟',
        a: '«اللهم أهله علينا باليُمن والإيمان، والسلامة والإسلام، ربي وربك الله»؛ وهي دعوة للبركة والطاعة في كل شهر هجري جديد يطل من تقويم الفردوس.',
        e: 'سنن الترمذي (3451)',
        t: ['دعاء الهلال', 'بداية الشهر الهجري'],
      ),
      (
        q: 'هل يجوز أن أدعو الله بأمر دنيوي خاص مثل وظيفة أو زواج أو نجاح؟',
        a: 'بالتأكيد! كان الصحابة يسألون الله كل حوائجهم حتى شسع النعل والملح للطعام؛ فالدعاء في الأمور الصغيرة والكبيرة دليل عبودية وافتقار لله وتوكل عليه في كل شؤون حياتك.',
        e: 'سنن الترمذي (3604 م)',
        t: ['الدعاء للوظيفة', 'الزواج', 'الدعاء الدنيوي'],
      ),
      (
        q: 'ماذا يقول من أصابه غضب أو نرفزة مفاجئة ليهدأ؟',
        a: '«أعوذ بالله من الشيطان الرجيم»، ثم يسكت، ويجلس إن كان قائماً أو يضطجع إن كان جالساً، ويتوضأ بالماء البارد، ويستغفر؛ وتجد في قسم «ساعدني» في تطبيق الفردوس تمرين التنفس التفاعلي لهذا تماماً.',
        e: 'متفق عليه وأبي داود (4784)',
        t: ['دعاء الغضب', 'النرفزة'],
      ),
      (
        q: 'ما أثر «حسبنا الله ونعم الوكيل» في طمأنينة القلب؟',
        a: 'هي شعار الخليل إبراهيم حين ألقي في النار فكانت برداً وسلاماً، وشعار النبي ﷺ وأصحابه في حمراء الأسد حين خُوّفوا بجمع الأعداء فانقلبوا بنعمة من الله وفضل؛ وتقولها عند الخوف وتفويض الأمر للوكيل.',
        e: 'صحيح البخاري (4563) وسورة آل عمران (173)',
        t: ['حسبنا الله ونعم الوكيل', 'التوكل'],
      ),
      (
        q: 'ما حكم المداومة على دعاء «يا حي يا قيوم برحمتك أستغيث»؟',
        a: 'هو من أعظم الكنوز النبوية ومن أدعية اسم الله الأعظم! وأوصى به النبي ﷺ ابنته فاطمة رضي الله عنها كل صباح ومساء: «يا حي يا قيوم برحمتك أستغيث، أصلح لي شأني كله، ولا تكلني إلى نفسي طرفة عين».',
        e: 'سنن النسائي الكبرى (10405) وحسنه الألباني',
        t: ['يا حي يا قيوم', 'أصلح لي شأني'],
      ),
      (
        q: 'ما معنى «لا يُلدغ المؤمن من جحر واحد مرتين» في حياة المسلم؟',
        a: 'أن المؤمن فطن يقظ لا يكرر نفس الأخطاء والتفريط في الدنيا ولا يستغفله أهل الشر مرتين؛ وكذلك في الذنوب والغفلة لا ينخدع بنفس مكيدة الشيطان مرة أخرى بل يتعلم ويستعد.',
        e: 'متفق عليه (البخاري 6133، مسلم 2998)',
        t: ['الحذر', 'الفطنة', 'لا يلدغ المؤمن'],
      ),
      (
        q: 'ما الفرق بين الاستغفار والتوبة؟',
        a: 'الاستغفار طلب المغفرة باللسان والقلب، وأما التوبة النصوح فهي عملية قلبية وسلوكية تشمل الندم والإقلاع عن الذنب فوراً والعزم الصادق على عدم العودة ورد المظالم لأصحابها؛ واجتماعهما يفتح كل مغاليق الرحمة.',
        e: 'مدارج السالكين لابن القيم',
        t: ['الفرق بين التوبة والاستغفار', 'التوبة النصوح'],
      ),
      (
        q: 'ما حكم تغير الألفاظ في الأذكار المأثورة أو الذكر برقم غير منصوص؟',
        a: 'التقيد باللفظ النبوي في الأذكار الموظفة (كأذكار الصباح والمساء والصلاة) أكمل وأعظم بركة؛ أما الذكر المطلق (كالاستغفار والتسبيح العام أثناء المشي أو في السبحة) فلا حد لأعداده: «يا أيها الذين آمنوا اذكروا الله ذكراً كثيراً».',
        e: 'سورة الأحزاب (41) وفتاوى العلماء',
        t: ['أعداد الذكر', 'الذكر المطلق'],
      ),
      (
        q: 'ما الدعاء المأثور عند الخوف من لقاء قوم أو مدير أو امتحان؟',
        a: '«اللهم إنا نجعلك في نحورهم ونعوذ بك من شرورهم»، وكذلك: «رب اشرح لي صدري ويسر لي أمري واحلل عقدة من لساني يفقهوا قولي»، ثم التفويض والثقة بالله.',
        e: 'سنن أبي داود (1537) وسورة طه (25-28)',
        t: ['دعاء الامتحان', 'المقابلة', 'الخوف من القوم'],
      ),
      (
        q: 'ما الأذكار الموصى بها قبل النوم لحماية النفس؟',
        a: 'تنفض فراشك وتنام على شقك الأيمن متوضئاً، وتقرأ آية الكرسي وخاتمة البقرة وسورة الملك وتجمع كفيك وتقرأ الإخلاص والفلق والناس وتمسح ما استطعت من جسدك ثلاثاً، وتسبح 33 وتكبر 34 وتحمد 33، وتقول: باسمك ربي وضعت جنبي...',
        e: 'متفق عليه وصحيح البخاري (5017 و6320)',
        t: ['أذكار النوم', 'قبل النوم'],
      ),
      (
        q: 'ما دعاء دخول الخلاء (الحمام) والخروج منه؟',
        a: 'قبل الدخول بالرجل اليسرى: «بسم الله، اللهم إني أعوذ بك من الخبث والخبائث» (الخبث: ذكران الشياطين، والخبائث: إناثهم)؛ وبعد الخروج بالرجل اليمنى تقول: «غفرانك».',
        e: 'متفق عليه وسنن الترمذي (7)',
        t: ['دعاء دخول الحمام', 'غفرانك'],
      ),
      (
        q: 'هل يستجاب الدعاء إذا دعوت لنفسي بغير عربية؟',
        a: 'نعم؛ الله عز وجل يعلم اللغات كلها ويسمع خفايا القلوب، فيجوز الدعاء خارج الصلاة بأي لغة يفهمها الداعي ويتذلل بها لربه، وأما الأذكار المقررة في الصلاة فيُحرص على تعلمها بالعربية.',
        e: 'مجموع الفتاوى لابن تيمية',
        t: ['الدعاء بلغة أخرى', 'غير العربية'],
      ),
      (
        q: 'كيف أربط لساني بذكر الله طوال اليوم وسط العمل والدراسة؟',
        a: 'اربط كل نشاط بمفتاح ذكر: عند الاستيقاظ الحمد، عند ركوب المواصلات الاستغفار 100 مرة، أثناء انتظار الطابور الصلاة على النبي ﷺ، وعند تعسر مسألة أو عمل قُل يا حي يا قيوم برحمتك أستغيث ولا حول ولا قوة إلا بالله.',
        e: 'الوابل الصيب لابن القيم',
        t: ['ذكر الله طوال اليوم', 'العمل والذكر'],
      ),
      (
        q: 'ما هي الباقيات الصالحات التي حثنا القرآن على استثمارها للآخرة؟',
        a: 'قال المفسرون وكبار الصحابة إن الباقيات الصالحات هي: «سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله» وكل عمل صالح تبتغي به وجه الله؛ تبقى لصاحبها يوم يفنى المال والبنون.',
        e: 'سورة الكهف (46) ومسند أحمد',
        t: ['الباقيات الصالحات', 'المال والبنون'],
      ),
      (
        q: 'هل يجب على من سمع الأذان أن يردد خلف المؤذن كل جملة؟',
        a: 'الترديد خلف المؤذن سنة نبوية عظيمة تجلب المغفرة والجنة إذا قاله من قلبه: يقول مثل ما يقول المؤذن إلا عند «حي على الصلاة، حي على الفلاح» فيقول: «لا حول ولا قوة إلا بالله»، ثم يصلي على النبي ﷺ ويسأل الله له الوسيلة.',
        e: 'صحيح مسلم (384 و385)',
        t: ['متابعة المؤذن', 'دعاء بعد الأذان'],
      ),
      (
        q: 'ما هي الدعوة النبوية الشاملة التي تجمع خير الدنيا والآخرة؟',
        a: 'أكثر دعاء كان يدعو به النبي ﷺ هو: «ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار»، ومن جوامع الكلم: «اللهم إني أسألك من الخير كله عاجله وآجله ما علمت منه وما لم أعلم، وأعوذ بك من الشر كله...»',
        e: 'متفق عليه (البخاري 6389) ومسند أحمد',
        t: ['جوامع الدعاء', 'آتنا في الدنيا حسنة'],
      ),
    ]);

    // =========================================================================
    // 8. السيرة النبوية والصحابة وآل البيت (351 - 400)
    // =========================================================================
    addCategory(IslamicQaCategory.seerah, [
      (
        q: 'متى ولد النبي محمد ﷺ وما اسمه ونسبه الشريف؟',
        a: 'هو محمد بن عبد الله بن عبد المطلب بن هاشم بن عبد مناف بن قصي، ينتهي نسبه إلى إسماعيل بن إبراهيم عليهما السلام؛ وُلد في مكة عام الفيل يوم الإثنين في ربيع الأول، ومات أبوه قبل ولادته وماتت أمه آمنة وهو ابن ست سنين.',
        e: 'الرحيق المختوم وصحيح مسلم (1162)',
        t: ['نسب النبي', 'مولد النبي', 'عام الفيل'],
      ),
      (
        q: 'لماذا عمل النبي ﷺ في رعي الغنم ثم التجارة قبل البعثة؟',
        a: 'ما بعث الله نبياً إلا رعى الغنم ليتربى على الصبر، والرحمة، والتواضع، واليقظة في حماية الضعيف؛ ثم عمل بالتجارة أميناً صادقاً فذاع لقبه بين قريش بـ «الصادق الأمين» حتى اختارته خديجة رضي الله عنها.',
        e: 'صحيح البخاري (2262)',
        t: ['رعي الغنم', 'الصادق الأمين', 'التجارة'],
      ),
      (
        q: 'من أول من آمن بالرسول ﷺ من الرجال والنساء والصبيان؟',
        a: 'أول من آمن به على الإطلاق أم المؤمنين خديجة بنت خويلد، ومن الرجال الأحرار أبو بكر الصديق، ومن الصبيان علي بن أبي طالب، ومن الموالي زيد بن حارثة رضي الله عنهم أجمعين.',
