      (
        q: 'لماذا لُقب عام 10 للبعثة بعام الحزن وماذا حدث بعده؟',
        a: 'لأن النبي ﷺ فقد فيه سنده الخارجي عمه أبا طالب، ثم بعد أيام فقد سنده الداخلي وزوجته الحبيبة أم المؤمنين خديجة، واشتد أذى قريش؛ ثم جاءه الفرج من الله برحلة الإسراء والمعراج جبراً لخاطره وتثبيتاً لرسالته.',
