        a: 'أن الصدق يهدي إلى النجاة ولو كان مراً ومؤلماً في لحظته؛ فقد صدق كعب بن مالك ولم يختلق الأعذار الكاذبة وهُجر خمسين يوماً حتى نزلت توبتهم تتلى إلى يوم القيامة: «يا أيها الذين آمنوا اتقوا الله وكونوا مع الصادقين».',
        e: 'صحيح البخاري (4418) وسورة التوبة (118-119)',
        t: ['كعب بن مالك', 'الصدق', 'التوبة'],
      ),
      (
        q: 'من هم الأربعة من غير العرب الذين ضربوا أروع الأمثلة في أخوة الإسلام؟',
        a: 'سلمان الفارسي (صاحب فكرة الخندق وقال النبي: سلمان منا آل البيت)، وصهيب الرومي (ترك ماله كله لمكة ليهاجر ويفوز بالآخرة: ربح البيع أبا يحيى)، وبلال الحبشي، وزيد بن حارثة (الوحيد الذي صُرح باسمه من الصحابة في القرآن).',
        e: 'تراجم الصحابة والرحيق المختوم',
        t: ['سلمان الفارسي', 'صهيب الرومي', 'الأخوة في الإسلام'],
      ),
      (
        q: 'ما قصة هجرة المسلمين الأولى إلى الحبشة وحماية النجاشي؟',
        a: 'لما اشتد أذى قريش للمستضعفين بمكة أذن لهم النبي ﷺ بالهجرة إلى الحبشة عند ملك عادل لا يُظلم عنده أحد (النجاشي)، فتلا جعفر بن أبي طالب مطلع سورة مريم فبكى النجاشي وآواهم، ثم أسلم وصلى عليه النبي ﷺ صلاة الغائب.',
        e: 'مسند أحمد وصحيح البخاري (1245)',
        t: ['هجرة الحبشة', 'النجاشي', 'جعفر بن أبي طالب'],
      ),
      (
        q: 'كيف تعامل النبي ﷺ مع الأعرابي الذي بال في المسجد؟',
        a: 'نهاهم النبي ﷺ عن تعنيفه والصراخ عليه، وأمرهم أن يدعوه حتى يتم حاجته ويهريقوا على البول دلواً من ماء، ثم ناداه برفق ولين وعلمه حرمة المسجد؛ فدعا الأعرابي: اللهم ارحمني ومحمداً ولا ترحم معنا أحداً!',
        e: 'صحيح البخاري (220 و6010)',
        t: ['الأعرابي في المسجد', 'الرفق في التعليم'],
      ),
      (
        q: 'من هي أم المؤمنين التي أشارت بحكمتها يوم الحديبية فأنهت أزمة الصحابة؟',
        a: 'أم سلمة هند بنت أبي أمية رضي الله عنها؛ لما شق على الصحابة التحلل من عمرتهم بالحديبية أشارت على النبي ﷺ بأن يخرج دون أن يكلم أحداً فيحلق وينحر، ففعل فتبادر الصحابة كلهم بالاقتداء به، وهكذا برز عقل المرأة المسلمة ومشورتها.',
        e: 'صحيح البخاري (2731)',
        t: ['أم سلمة', 'مشورة المرأة', 'الحديبية'],
      ),
      (
        q: 'ما قصة «غزوة الخندق» وكيف حوّل المسلمون الحصار إلى نصر؟',
        a: 'تحزبت عشرة آلاف مقاتل لإبادة المدينة، فاستشار النبي ﷺ أصحابه وقبل فكرة سلمان الفارسي بحفر الخندق في سابقة عسكرية بالجزيرة، وحرسوا بعيون ساهرة وتضرع حتى أرسل الله ريحاً وجنوداً هزمت الأحزاب دون قتال شامل.',
        e: 'سورة الأحزاب وصحيح البخاري',
        t: ['الخندق', 'الأحزاب', 'الشورى'],
      ),
      (
        q: 'ما هو وثيقة المدينة النبوية وما أهميتها الحضارية؟',
        a: 'أول دستور مدني مكتوب في التاريخ نظّم التعايش السلمي وحقوق المواطنة والعدل والأمن والدفاع المشترك بين المسلمين من قريش والأنصار والقبائل اليهودية وغيرهم بمجرد هجرة النبي ﷺ للمدينة.',
        e: 'سيرة ابن هشام',
        t: ['وثيقة المدينة', 'الدستور الأول', 'التعايش'],
      ),
      (
        q: 'ما سبب غزوة أُحد وما الخطأ الذي يجب ألا يكرره المسلم؟',
        a: 'انقلب النصر المؤكد في غزوة أُحد إلى هزيمة مؤلمة بسبب مخالفة الرماة لأمر قائدهم الرسول ﷺ ونزولهم من الجبل طمعاً في الغنائم قبل الأوان؛ فتعلمت الأمة أن مخالفة أمر الوحي والانشغال بالدنيا قبل تمام المهمة سبب الخسارة.',
        e: 'سورة آل عمران (152) وصحيح البخاري',
        t: ['غزوة أحد', 'جبل الرماة', 'الطاعة'],
      ),
      (
        q: 'من الذي حمل اللواء في فتح خيبر ونال شرف محبة الله ورسوله؟',
        a: 'علي بن أبي طالب رضي الله عنه! قال ﷺ: «لأعطين الراية غداً رجلاً يحب الله ورسوله ويحبه الله ورسوله»، وتفل في عينيه الرمدتين فبرئتا في الحال وفتح الله على يديه خيبر.',
        e: 'متفق عليه (البخاري 3009، مسلم 2406)',
        t: ['علي بن أبي طالب', 'خيبر', 'محبة الله'],
      ),
      (
        q: 'ما أعظم صفات عثمان بن عفان ذي النورين رضي الله عنه؟',
        a: 'الحياء العظيم الذي تستحيي منه الملائكة، والكرم الهائل في سبيل الله (اشترى بئر رومة للمسلمين وجهز جيش العسرة بماله)، وجمع القرآن في المصحف الإمام الذي يجمع الأمة حتى اليوم.',
        e: 'صحيح مسلم (2401) وسنن الترمذي (3701)',
        t: ['عثمان بن عفان', 'جمع القرآن', 'جيش العسرة'],
      ),
      (
        q: 'ما دور القائد البطل معاذ بن جبل في فقه الأمة وتبليغها؟',
        a: 'أعلم الأمة بالحلال والحرام وبعثه النبي ﷺ معلماً وقاضياً إلى اليمن ليرسي منهج القضاء بالقرآن ثم السنة ثم الاجتهاد، وحبه النبي ﷺ قائلاً: «يا معاذ والله إني لأحبك» وعلمه الدعاء دبر كل صلاة.',
        e: 'سنن أبي داود (1522 و3592)',
        t: ['معاذ بن جبل', 'اليمن', 'الفقه'],
      ),
      (
        q: 'كيف استقبلت السيدة فاطمة مرض النبي ﷺ ووفاته؟',
        a: 'أسرّ إليها ﷺ بقرب أجله فبكت، ثم أسرّ إليها بأنها أول أهل بيته لحوقاً به وبأنها سيدة نساء أهل الجنة فضحكت! وتوفيت بعده ﷺ بستة أشهر صابرة راضية رضي الله عنها.',
        e: 'متفق عليه (البخاري 3623، مسلم 2450)',
        t: ['فاطمة الزهراء', 'سيدة نساء الجنة'],
      ),
      (
        q: 'ما موقف الشجاعة العجيب لأبي دجانة والزبير في أُحد؟',
        a: 'ترس أبو دجانة بظهره أمام السهام ليحمي جسد النبي ﷺ من الطعنات فصارت النبال كالقنفذ في ظهره وهو صامد، والزبير بن العوام كان أول من سل سيفه في سبيل الله وحواريّ الرسول ﷺ.',
        e: 'صحيح البخاري (3720 و4064)',
        t: ['أبو دجانة', 'الزبير بن العوام', 'الفداء'],
      ),
      (
        q: 'ما معنى أن الرسول ﷺ «وما أرسلناك إلا رحمة للعالمين»؟',
        a: 'شملت رحمته ﷺ البشرية جمعاء: المسلم والكافر (بتأخير عذاب الاستئصال وفتح باب الهداية)، المرأة، الطفل، الضعيف، الأسير، واليتيم، والحيوان والطير والنبات؛ فنهى عن تحريق النمل وعن تعذيب البهائم وحبس الهرة.',
        e: 'سورة الأنبياء (107) وصحيح مسلم',
        t: ['رحمة للعالمين', 'الرفق بالحيوان'],
      ),
      (
        q: 'كيف حافظ النبي ﷺ على صحته البدنية والنظافة اليومية؟',
        a: 'كان أكثر الناس تبسماً ونظافةً: يبدأ نومه واستيقاظه وكل صلاة بالسواك، ويمشط شعره ويدّهن ويستعمل الطيب دائماً، ولا يأكل إلا طيباً، ويقسم طعامه ثلثاً للطعام وثلثاً للشراب وثلثاً للنفس، ويسابق أهله مشياً.',
        e: 'الشمائل المحمدية وسنن الترمذي (2380)',
        t: ['صحة النبي', 'السواك', 'الأكل الصحي'],
      ),
      (
        q: 'ما هي معجزات النبي محمد ﷺ الخالدة إلى يوم القيامة؟',
        a: 'أعظم معجزاته الخالدة «القرآن الكريم» الذي يتحدى العقول والقلوب على مر العصور في بيانه وتشريعه ونبوءاته، بالإضافة لمعجزات حسية كثيرة شهدتها الجموع: انشقاق القمر، ونبع الماء من بين أصابعه، وتكثير الطعام، وحنين الجذع.',
        e: 'متفق عليه وسورة القمر (1)',
        t: ['معجزات النبي', 'القرآن', 'انشقاق القمر'],
      ),
      (
        q: 'كيف أكون قريباً من النبي ﷺ كأني أراه في حياتي اليومية؟',
        a: 'تعلّم الشمائل المحمدية وسننه اليومية (في الأكل والشرب والنوم والسلام والابتسامة والاستغفار)، واقتدِ به في التواضع ورحمة أهل بيتك، وداوم على السلام عليه عند كل أذان وفي كل مجلس!',
        e: 'مناهج السيرة والشمائل',
        t: ['تطبيق السنة', 'اتباع النبي'],
      ),
    ]);

    // =========================================================================
    // 9. الأسرة وبر الوالدين والزواج والأخلاق (401 - 450)
    // =========================================================================
    addCategory(IslamicQaCategory.familyEthics, [
      (
        q: 'ما حدود بر الوالدين وهل تجوز طاعتهما في ترك واجب أو فعل محرم؟',
        a: 'بر الوالدين والإحسان إليهما وخفض الجناح والدعاء لهما أحياءً وأمواتاً أعظم الفرائض بعد التوحيد، ويجب طاعتهما في كل ما لا معصية فيه؛ أما إن أمرا بمعصية أو ظلم فلا طاعة لمخلوق في معصية الخالق ولكن يُصاحبان بالمعروف والأدب والرفق.',
        e: 'سورة لقمان (15) وسورة الإسراء (23-24)',
        t: ['بر الوالدين', 'طاعة الوالدين', 'العقوق'],
      ),
      (
        q: 'كيف أبر والديّ بعد وفاتهما؟',
        a: 'باب البر لا يُغلق بالموت! تُبرهما بكثرة الدعاء والاستغفار لهما، والصدقة الجارية عنهما (كسقيا ماء أو مصحف أو نفع للفقراء)، وإنفاذ عهدهما ووصاياهما المشروعة، وصلة الرحم التي لا توصل إلا بهما، وإكرام أصدقائهما.',
        e: 'سنن أبي داود (5142)',
        t: ['بر الوالدين بعد الوفاة', 'الأم المتوفاة', 'الأب المتوفى'],
      ),
      (
        q: 'ماذا أفعل إذا كان أقاربي يقطعونني ويؤذونني؟ هل أقطعهم؟',
        a: 'ليس الواصل بالمكافئ! وإنما الواصل من إذا قُطعت رحمه وصلها. لا تعامل الإساءة بقطيعة مثلها، بل تواصل بالحد الذي يرفع إثم القطيعة (اتصال أو تهنئة أو زيارة) دون أن تضر نفسك إن كان في الخلطة أذى شديد.',
        e: 'صحيح البخاري (5991) وصحيح مسلم (2558)',
        t: ['صلة الرحم', 'الأقارب المؤذون', 'القطيعة'],
      ),
      (
        q: 'ما هي مواصفات اختيار الزوج الصالح والزوجة الصالحة؟',
        a: 'للرجل: «فاظفر بذات الدين تربت يداك» ذات الخلق والستر وحسن المعشر؛ وللمرأة وأوليائها: «إذا خطب إليكم من ترضون دينه وخلقه فزوجوه»، مع مراعاة الكفاءة والراحة النفسية والقبول المتبادل.',
        e: 'متفق عليه وسنن الترمذي (1084)',
        t: ['اختيار الزوج', 'اختيار الزوجة', 'الزواج'],
      ),
      (
        q: 'ما حق الزوجة على زوجها وما حق الزوج على زوجته؟',
        a: 'الزواج سكن ومودة ورحمة، وقوامته تكليف بالرعاية والنفقة والحماية واللطف («خيركم خيركم لأهله»)، وحق الزوجة النفقة الكريمة والمسكن والمعاشرة بالمعروف وحفظ كرامتها، وحق الزوج الطاعة في المعروف وصيانة بيته وماله واللطف معه.',
        e: 'سورة الروم (21) وسنن الترمذي (3895)',
        t: ['حقوق الزوجين', 'العشرة بالمعروف', 'خيركم لأهله'],
      ),
      (
        q: 'هل يجوز للرجل مساعدة زوجته في أعمال المنزل ورعاية الأطفال؟',
        a: 'هذا من أرقى سنن النبي ﷺ وتمام الرجولة والمودة! قالت السيدة عائشة رضي الله عنها: «كان النبي ﷺ في مهنة أهله (يعني خدمة أهله)، فإذا حضرت الصلاة خرج إلى الصلاة».',
        e: 'صحيح البخاري (676)',
        t: ['مساعدة الزوجة', 'البيت', 'أعمال المنزل'],
      ),
      (
        q: 'ما حكم الضرب والإهانة في الخلافات الزوجية أو تربية الأبناء؟',
        a: 'الرسول ﷺ لم يضرب بيده امرأة قط ولا خادماً قط ولا ولداً! وضرب الوجه أو الإهانة والشتم محرم مطلقاً، والضرب المؤذي محرم ومخالف للرحمة النبوية؛ وإنما تُعالج المشاكل بالحوار الهادئ، والتقدير، والرفق، والاستشارة الإصلاحية عند الحاجة.',
        e: 'صحيح مسلم (2328)',
        t: ['ضرب الزوجة', 'تربية الأطفال', 'العنف الأسري'],
      ),
      (
        q: 'ما هي أركان النكاح الشرعي الذي يكون به الزواج صحيحاً حلالاً؟',
        a: 'الرضا والقبول بين الزوجين، وموافقة ولي المرأة، والمهر (الصداق)، وشاهدان عدلان، والإعلان والإشهار ليُفَرَّق بين النكاح الصحيح والسفاح السري؛ وأعظم الزواج بركة أيسره مؤونة.',
        e: 'سنن أبي داود (2085) ومسند أحمد',
        t: ['أركان الزواج', 'العقد الشرعي', 'المهر'],
      ),
      (
        q: 'ما هو الزواج السري أو العرفي وهل يجوز؟',
        a: 'النكاح الذي يخلو من الولي أو الإشهار والشاهدين باطل عند جمهور العلماء؛ وزواج السر الذي تتستر فيه المرأة عن أهلها بالكلية بدون ولي مذموم وممنوع لحفظ حقوق الزوجة والأولاد؛ فليُوثّق الزواج رسمياً وعلنياً على السنة.',
        e: 'المجموع وسنن الترمذي (1101 - أيما امرأة نكحت بغير إذن وليها)',
        t: ['الزواج العرفي', 'الزواج السري', 'الولي'],
      ),
      (
        q: 'كيف نربي أبناءنا على الصلاة وحب الله بدون تنفير؟',
        a: 'بالقدوة العملية والرحمة والمكافأة التشجيعية! نأمرهم بلطف عند السبع بالتدريب والمشاركة الجماعية في البيت، ونحكي لهم عن رحمة الله والجنة قبل النار، ونثني على إنجازاتهم في سجل ومهام الفردوس دون عقاب بدني منفّر.',
        e: 'سنن أبي داود (495)',
        t: ['تربية الأبناء على الصلاة', 'الأطفال والصلاة'],
      ),
      (
        q: 'هل يجب العدل والمساواة بين الأولاد في العطية والهدايا؟',
        a: 'نعم؛ يجب العدل بين الأبناء ذكوراً وإناثاً في الهدايا والعطايا المجردة: «اتقوا الله واعدلوا بين أولادكم»؛ أما ما يحتاجه أحدهم لعلاج أو تعليم أو نفقات حاجة خاصة فتعطى له بقدر حاجته دون ظلم للآخرين.',
        e: 'متفق عليه (البخاري 2587، مسلم 1623)',
        t: ['العدل بين الأولاد', 'العطية للأبناء'],
      ),
      (
        q: 'كيف أحفظ حق الجار ولو لم يكن قريباً أو مسلماً؟',
        a: 'أوصى جبريل النبي ﷺ بالجار حتى ظن أنه سيورثه! حق الجار كف الأذى عنه (كالإزعاج الصوتي ومواقف السيارات والقمامة)، وتبادل السلام والهدية وطعاماً طيباً، وتفقد أحواله عند المرض والفرح والضيق، وللجار سواء كان مسلماً أو غير مسلم حق الجوار.',
        e: 'متفق عليه (البخاري 6014، مسلم 47)',
        t: ['حق الجار', 'الجيران'],
      ),
      (
        q: 'ما هي كفارة الغيبة والنميمة إذا وقعت فيها بحق أحد؟',
        a: 'التوبة والندم والعزم على عدم العود، ثم الدعاء والاستغفار لمن اغتبته في ظهر الغيب، والثناء عليه بصفاته الطيبة في نفس المجالس التي ذكرته فيها بسوء؛ ولا يلزم إخبار الشخص إذا كان إخباره سيولد عداوة وفتنة أكبر على الراجح.',
        e: 'اختيار ابن تيمية وابن القيم في الوابل الصيب',
        t: ['كفارة الغيبة', 'النميمة', 'المسامحة'],
      ),
      (
        q: 'ما الفرق بين الغيبة الجائزة والنصيحة وبين الغيبة المحرمة؟',
        a: 'الأصل تحريم ذكر أخيك بما يكره حتى ولو كان فيه! وتُباح فقط في ست حالات للضرورة بقدر الحاجة: التظلم للقاضي، الاستعانة على تغيير منكر، الاستفتاء، تحذير المسلمين من غشاش أو مجرم، المجاهر بفسقه، أو للتعريف بوصف لا يقصد به تنقيص (كالأعمى والأعرج إذا لم يعرف إلا به).',
        e: 'رياض الصالحين للنووي',
        t: ['الغيبة الجائزة', 'التحذير', 'النصيحة'],
      ),
      (
        q: 'كيف أتعامل مع شخص حسود أو يغار من نعمتي؟',
        a: 'بالكتمان اللبق عند بدء الخطوات («استعينوا على قضاء حوائجكم بالكتمان»)، والمحافظة على أذكار التحصين، وإظهار التواضع وشكر الله، وعدم مقابلة حسده بمثل بل الدعاء له بالبركة ليصرف الله شره.',
        e: 'سورة الفلق وسنن الترمذي وصحيح الجامع',
        t: ['الحسود', 'الكتمان', 'قضاء الحوائج'],
      ),
      (
        q: 'هل يجب احترام الكبير والرحمة بالصغير في كل حال؟',
