        t: ['توقير الكبير', 'الرحمة بالصغير'],
      ),
      (
        q: 'ما حكم قطيعة المسلم والهجر أكثر من ثلاثة أيام بسبب خلاف؟',
        a: 'لا يحل لمسلم أن يهجر أخاه فوق ثلاث ليالٍ يلتقيان فيعرض هذا ويعرض هذا، وخيرهما الذي يبدأ بالسلام! فإن بدأ المسلم بالسلام وأبى الآخر زال الإثم عن المبادر؛ وإن كان في الخلطة ضرر ديني أذِن الشرع في الاكتفاء بالسلام والتواصل الظاهري البعيد.',
        e: 'متفق عليه (البخاري 6077، مسلم 2560)',
        t: ['الخصام', 'الهجر', 'ثلاث ليال'],
      ),
      (
        q: 'ما هو فضل التبسم والكلمة الطيبة وجبر الخواطر؟',
        a: '«تبسمك في وجه أخيك لك صدقة»، و«الكلمة الطيبة صدقة»؛ بل قد يُفتح لك باب الجنة بإدخال السرور على قلب مكروب أو مسح دمعة يتيم أو جبر خاطر والديك.',
        e: 'سنن الترمذي (1956) وصحيح البخاري (2989)',
        t: ['التبسم', 'الكلمة الطيبة', 'جبر الخواطر'],
