      (
        q: 'ما حكم الحسد وماذا يفعل من وجد في نفسه حسداً لغيره؟',
        a: 'الحسد هو تمني زوال النعمة عن الغير، وهو يأكل الحسنات ويرد الاعتراض على قسمة الله؛ وإذا رأيت نعمة عند غيرك فعليك فوراً بالدعاء له: «اللهم بارك له وأرزقني مثله من فضلك» (وهذه الغبطة المحمودة).',
        e: 'سورة النساء (32) وصحيح البخاري (73)',
        t: ['الحسد في النفس', 'الغبطة', 'البركة'],
      ),
      (
        q: 'كيف يتعامل الزوجان إذا وصل الخلاف إلى طلب الطلاق؟',
        a: 'الطلاق أبغض الحلال أو آخر العلاج؛ قبله تُتبع خطوات الإصلاح: المصارحة الهادئة، تنازل كل طرف عن جزء من حظ نفسه، استعانة بحكمين عاقلين أمينين من الأهلين؛ فإن استحال الوفاق ووقع الطلاق فليكن «تسريح بإحسان» دون انتقام أو حرمان من الأولاد والنفقة.',
        e: 'سورة النساء (35) وسورة البقرة (229)',
        t: ['الطلاق', 'الإصلاح الزوجي', 'التسريح بإحسان'],
