      (
        q: 'ما حكم تعدد الزوجات وما شرطه الأساسي الصارم؟',
        a: 'أباح الإسلام التعدد بحد أقصى أربعاً مقيداً بشرط صارم واضح في القرآن: «فإن خفتم ألا تعدلوا فواحدة»؛ والعدل المطلوب في النفقة والمسكن والمبيت وحسن المعاملة، مع توعد من يميل لإحداهن ويذر الأخرى كالمعلقة بأن يأتي يوم القيامة وشقه مائل!',
        e: 'سورة النساء (3) وسنن أبي داود (2133)',
        t: ['تعدد الزوجات', 'العدل بين الزوجات'],
