        q: 'هل يجوز للرجل أو المرأة كشف أسرار الحياة الزوجية للأصدقاء أو الأهل؟',
        a: 'إفشاء الأسرار الخاصة بين الزوجين من أشد المحرمات ومنافي للمروءة: «إن من أشر الناس عند الله منزلة يوم القيامة الرجل يفضي إلى امرأته وتفضي إليه ثم ينشر سرها»؛ ولا يُباح الشكوى إلا بقدر الحاجة لمصلح أمين أو مستشار نفسي أو قاضٍ.',
        e: 'صحيح مسلم (1437)',
        t: ['أسرار الزوجين', 'المشاكل الزوجية'],
