      (
        q: 'ما حكم تأخير الزواج للشباب مع عدم القدرة المادية؟',
        a: 'لا يعقّد الأهل المهور، بل «أعظم النساء بركة أيسرهن مؤونة»؛ فإن لم يجد الشاب باءة الزواج بعد السعي الحلال والجد فليستعفف بالصيام وغض البصر والرياضة وصحبة الخير، وسيرزقه الله من فضله ويكتب له أجر العفة كالمجاهد.',
        e: 'متفق عليه وسورة النور (33)',
        t: ['تأخر الزواج', 'العفة', 'المهور'],
      ),
      (
        q: 'كيف تعامل الخادم أو السائق أو العامل تحت يدك؟',
        a: 'أمره ﷺ بإطعامهم مما نأكل وإكسائهم وألا نكلفهم ما يغلبهم فإن كلفناهم فلنُعنهم، والأمر الأهم إعطاؤهم أجورهم كاملة بدون مماطلة: «أعطوا الأجير أجره قبل أن يجف عرقه»، والكلمة الطيبة وتقدير تعبهم.',
