        q: 'ما هي كفارة اليمين (الحلف) إذا حنث الإنسان فيه؟',
        a: 'إذا حلفت على شيء ثم رأيت خيراً منه (كأن حلفت ألا تزور قريبك ثم تراجعت فزرته)، تأتي الذي هو خير وتُكفّر عن يمينك فوراً بإطعام عشرة مساكين أو كسوتهم؛ فإن لم تجد مالاً لها فصيام ثلاثة أيام.',
        e: 'سورة المائدة (89) وصحيح مسلم (1652)',
        t: ['كفارة اليمين', 'الحلف'],
      ),
      (
        q: 'ما حكم النذر وهل يفضل الإكثار من النذور؟',
