        e: 'متفق عليه (البخاري 6608، مسلم 1639)',
        t: ['النذر', 'الوفاء بالنذر'],
      ),
      (
        q: 'هل يجب على الابنة العاملة أن تعطي راتبها لزوجها أو أبيها؟',
