        t: ['الحياء', 'التفقه في الدين'],
      ),
      (
        q: 'كيف نتغلب على الكِبر والغرور في القلب؟',
        a: '«لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر»؛ والكبر هو بطر الحق (رده إذا خالف هواك) وغمط الناس (احتقارهم)! وعلاجه التذكر بأن أصلك من تراب ومعادك للتراب، ومجالسة الفقراء، ومبادرة الناس بالسلام، وقبول النصيحة من صغير وكبير.',
