        a: 'من أكبر الكبائر وأشدها تحريماً على الإطلاق! لأن اليمين الغموس تغمس صاحبها في الإثم وتقتطع مال المسلم بغير حق، وشهادة الزور تهدم الحقوق؛ والواجب التوبة ورد الحقوق فوراً إلى أصحابها.',
