        t: ['شهادة الزور', 'اليمين الغموس', 'الكذب'],
      ),
      (
        q: 'ما هي نصيحة الإسلام في الرفق بالحيوان؟',
        a: 'الإسلام دين رحمة شاملة؛ أخبر ﷺ أن امرأة عُذبت في هرة حبستها فلا أطعمتها ولا تركتها تأكل، وغُفر لبغيّ من بني إسرائيل لما سقت كلباً؛ وأمرنا بإحداد الشفرة عند الذبح وإراحة الذبيحة وعدم تحميل الدابة فوق طاقتها أو تعذيب أي مخلوق.',
