      (
        q: 'هل يجوز المزاح والضحك في الإسلام وما حدوده؟',
        a: 'نعم! كان النبي ﷺ يمزح مع أهله وأصحابه وتبدو نواجذه من التبسم لكنه «لا يقول إلا حقاً»؛ فالحدود الشرعية للمزاح هي: عدم الكذب لإضحاك الناس، وعدم السخرية والاستهزاء واللمز بالآخرين، وعدم الترويع، وألا يضيع الهيبة والوقت بالانغماس الدائم.',
