      (
        q: 'كيف يتعامل الابن إذا كانت الأم تظلم الزوجة أو العكس؟',
        a: 'أنت نقطة التوازن والحكمة بين أقدس علاقتين! فلا تطع زوجتك في عقوق أمك ولا تنهر أمك، ولا تظلم زوجتك إرضاءً لهوى؛ بل احفظ لأمك كرامتها وتودد إليها سراً وعلناً، واعدل مع زوجتك في السكن والنفقة والطيبة دون نقل كلام السلبيات بين الطرفين أبداً.',
