        q: 'ما حكم تسمية الأبناء بأسماء غير عربية أو أسماء أجنبية؟',
        a: 'أحب الأسماء إلى الله عبد الله وعبد الرحمن وأصدقها حارث وهمام، وتُستحب الأسماء الجميلة المعنى للأنبياء والصحابة والصالحين والأسماء العربية اللطيفة؛ وتُحرم الأسماء التي فيها تعبيد لغير الله أو تزكية كاذبة أو قبح معنى، أما الأسماء الطيبة المعنى من لغات مباحة فلا تحرم إذا لم تكن شعاراً لغير دين الله.',
