      (
        q: 'هل للمحافظة على الصدق والأمانة في التجارة والعمل أجر خاص؟',
        a: 'التاجر الصدوق الأمين يُبعث يوم القيامة مع النبيين والصديقين والشهداء! وموظف العمل المتقن الذي يؤدي أمانته بلا غش ولا تأخير ولا رشوة يُثاب على كل ساعة عمل كعبادة.',
        e: 'سنن الترمذي (1209)',
        t: ['الأمانة في العمل', 'التجارة الصادقة'],
      ),
      (
        q: 'ما حكم كشف عورة الطفل أو الرضيع وما سن الاحتشام؟',
