        t: ['التفريق في المضاجع', 'حياء الأطفال'],
      ),
      (
        q: 'كيف تتعامل مع صديق يجرّك إلى المعاصي أو التفريط؟',
        a: 'المرء على دين خليله فلينظر أحدكم من يخالل! انصحه برفق فإن استجاب وتعاونا على الخير فبها، وإلا فابتعد عن مجالس المعصية بلطف وبلا قطيعة قاسية ما دام يحاول جرك للوراء، واستبدله بصحبة تعينك على طاعة الله.',
