        a: 'من عاد مريضاً أو زار أخاً له في الله لم يزل في خُرفة الجنة (جناها وثمارها) حتى يرجع، ويصلي عليه سبعون ألف ملك حتى يمسي أو حتى يصبح؛ فليخفف الزيارة ولا يثقل بالجلوس الطويل.',
