        a: 'قال النبي ﷺ: «لا تُظهر الشماتة لأخيك فيرحمه الله ويبتليك»! فالبلاء ليس مادة للسخرية بل للتواضع لله والشفقة على الخلق وسؤال الله العافية والسلامة في الدنيا والآخرة.',
