    // =========================================================================
    addCategory(IslamicQaCategory.lifeTawbah, [
      (
        q: 'أتوب من ذنب مراراً ثم أضعف وأعود إليه؛ فهل يقبل الله توبتي مجدداً؟',
        a: 'إياك واليأس والقنوط؛ فالله لا يمل حتى تملوا! كلما وقعت انهض فوراً وتوضأ وصلِّ ركعتين واندَم وأقلِع وتُب بصدق دون استهانة؛ وقد ورد في الحديث القدسي الصحيح: أذنب عبد ذنباً فقال ربِّ اغفر لي... ثم عاد فاستغفر... فقال الله: «علم عبدي أن له رباً يغفر الذنب ويأخذ به، قد غفرت لعبدي»!',
        e: 'متفق عليه (البخاري 7507، مسلم 2758)',
        t: ['تكرار الذنب', 'العودة للذنب', 'قبول التوبة'],
