        a: 'إذا كانت حقوقاً مادية لأشخاص معلومين فيجب ردها إليهم ولو بطريقة غير مباشرة تضمن حفظ السرية وعدم الشجار (كحوالة مجهولة أو هدية بقيمة الحق)؛ فإن عجزت عن الوصول إليهم أو ورثتهم نهائياً فتصدق بها عنهم بنية أن يصلهم أجرها يوم القيامة.',
