        a: 'أجاز أكثر المجامع الفقهية «التأمين التعاوني والتكافلي» القائم على التبرع والمشاركة لرفع الأضرار؛ وأما التأمين الإجباري الذي تفرضه الدولة للسيارات أو العمل الطبي فلا إثم على المواطن المُلزم به، ويأخذ منه فقط بقدر علاجه أو تعويض ضرره الفعلي.',
